        path: 'lessons/621-zheng-dui-rang/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》四支其四开篇。原文：「争对让，望对思。野葛对山栀。仙风对道骨，天造对人为。」争是抢在前头、把东西往自己手里夺，让是退后一步、把好处先给人，一进一退；望是远远地看、久久地盼，望子成龙、望穿秋水，眼睛朝外，思是心里放不下、一遍一遍想，心思朝内，一外一内，平仄也合，争平让仄、望仄思平。野葛对山栀：葛念 gé，多年生藤本，爬树缠篱，根肥大能洗葛根粉，皮上纤维能织葛布，是古人夏衣的料；栀念 zhī 即栀子，常绿灌木，夏初开白花、香气远，果实赤黄能染黄布也能入药；一藤一木，野对山都说不在园中。仙风是仙人的风度，飘然不沾烟火；道骨是修道者的骨相，清瘦有神；合起来是成语「仙风道骨」，赞人气度不凡，不是真说神仙。天造是天然生成，人为是人力做成，一自然一人工，反义相对，最见工整。全句三层：心上事对心上事、山上物对山上物、道理对道理，虚虚实实错开排。韵脚思、栀、为，同押四支；让为仄声收句不入韵。',
