        description: '《笠翁对韵》六鱼其三末段。原文：「南阳高士吟梁父，西蜀才人赋子虚。三径风光，白石黄花供杖履；五湖烟景，青山绿水在樵渔。」南阳高士是诸葛亮，年轻时隐居南阳隆中，「躬耕陇亩，好为《梁父吟》」；《梁父吟》是乐府古曲，梁父是泰山下的小山，古辞唱晏婴二桃杀三士，调子苍凉；父念 fǔ，不念 fù。西蜀才人是司马相如，蜀郡成都人，作《子虚赋》，借子虚、乌有先生、亡是公三人对话铺陈苑囿之盛；汉武帝读后叹「朕独不得与此人同时哉」，同乡杨得意举荐，皇帝立刻召见。三径：西汉末蒋诩辞官隐居，院中开三条小路，只与求仲、羊仲来往；陶渊明「三径就荒，松菊犹存」，三径遂成隐士家园的代称；黄花即菊，白石黄花供老人拄杖漫步，供念 gōng。五湖：范蠡助越王灭吴后功成身退，乘扁舟泛游五湖，泛指太湖一带；樵渔是打柴捕鱼，青山绿水归了靠山水吃饭的人。落点：上两句一吟一赋、两个不得志的大才；下两句一园一湖、两种退隐的活法——全段只写一个字：隐。韵脚父、虚、渔，同押六鱼，六鱼韵到此完结。',
