        path: 'lessons/657-men-dui-hu/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》九佳其一第一段，八齐讲完后的新韵开篇。原文：「门对户，陌对街。枝叶对根荄。斗鸡对挥麈，凤髻对鸾钗。」门是两扇的大门，户是单扇的小门，《说文》「半门曰户」，门户连称即指一家，故有「门当户对」之说，讲的是两家门第相当。陌读 mò，是田间小路，《桃花源记》「阡陌交通，鸡犬相闻」；街是城中大路，唐长安朱雀大街宽可通车马，一在乡一在城。枝叶是树的上部，长在明处；荄读 gāi，是草根，埋在土中；古人讲本末，本在根、末在梢，枝叶再茂，根烂则树死，故看树先看根。斗鸡是古时游戏，上上下下都玩，唐玄宗于宫中设鸡坊养鸡数千，李白「斗鸡金宫里，蹴鞠瑶台边」；挥麈的麈读 zhǔ，是鹿一类的兽，尾毛可作大拂尘，魏晋名士清谈时手执麈尾边谈边挥，故称「挥麈清谈」，一俗一雅，皆为手上动作。凤髻是盘成凤形的发髻，髻读 jì，欧阳修「凤髻金泥带，龙纹玉掌梳」；鸾钗是鸾鸟形的发钗，钗读 chāi，为两股簪子，插发压髻；凤、鸾皆神鸟，成双以比夫妻。四句由门口、田间写到树下、席上，最后落到女子头顶，由大收小、由外向内。落点：看根不看梢。韵脚街、荄、钗，同押九佳。',
