        description: '《笠翁对韵》九佳其二第一段，其一已讲完。原文：「冠对履，袜对鞋。海角对天涯。鸡人对虎旅，六市对三街。」冠读 guān，为名词「帽子」，古时男子二十岁行冠礼，作动词「戴帽」「居首」则读 guàn；履读 lǚ，为古时对鞋的称呼，亦作踩、走讲，如「如履薄冰」；「鞋」为后起之字。袜读 wà，古字作襪，足衣，穿在鞋内。二对分上下与内外。海角为陆地伸入海中的尽头，海南三亚有「天涯海角」刻石；涯读 yá，为水边亦指边际，天涯即天边，韩愈《祭十二郎文》「一在天之涯，一在地之角」，二词同义相对。鸡人为宫中报晓之官，头戴红巾，《周礼》设鸡人掌共鸡牲并司报时，天将明时呼唱而百官起身。虎旅谓勇猛之军，古称勇士为虎贲，取其如虎奔走逐兽；旅为军制，五百人为一旅。六街指唐长安城六条主干大街，后为都城代称；三市出《周礼》，分朝市、大市、夕市，一日三回买卖；合称三街六市，泛指繁华街市。四句由穿戴写到天边，再由人写到街市，由身及世，由远及近。落点：走得再远，也别忘了人间烟火。韵脚鞋、涯、街，同押九佳。',
