        description: '《笠翁对韵》九佳其二第三段，本段收束其二。原文：「梦里山川书越绝，枕边风月记齐谐。三径萧疏，彭泽高风怡五柳；六朝华贵，琅琊佳气种三槐。」越绝即《越绝书》，东汉袁康、吴平所撰，记吴越两国史事，今本十五卷；「越」为越国，「绝」为断绝，谓越事记至此处而止。齐谐出《庄子·逍遥游》「齐谐者，志怪者也」，本指齐国一部专记怪异之书，南朝宋又有《齐谐记》七卷；谐读 xié。梦里对枕边，一虚一实；山川对风月，一在地一在天；书对记，越绝对齐谐，皆为书名，四字相偶极工。三径用汉蒋诩事，王莽当权时隐居不仕，院中竹下开三径，唯与求仲、羊仲往来，后为隐者家园之代称，陶渊明《归去来兮辞》「三径就荒，松菊犹存」即用此；萧疏谓路荒人稀。彭泽指陶渊明，曾为彭泽令八十余日，不愿为五斗米折腰而归，宅边有五柳，自号五柳先生，怡为使动，谓高风在五柳间自得其乐。六朝指吴、东晋、宋、齐、梁、陈，皆都建康，朝读 cháo。琅琊为郡名，今山东临沂一带，琅琊王氏为东晋第一家，王导辅晋元帝，时称「王与马，共天下」，佳气谓祥瑞之气。三槐本周代外朝植三槐、三公位其下之制，故为三公之代称，宋王祐植槐于庭，期后世出三公，子王旦果为相，苏轼作《三槐堂铭》；种读 zhòng。四句前写两部书，后写两种人，一退一进。落点：心里装得下山川，也看得清进退。韵脚谐、槐，同押九佳。',
