        description: '《笠翁对韵》九佳其三开篇，其二已讲完。原文：「勤对俭，巧对乖。水榭对山斋。冰桃对雪藕，漏箭对更牌。」勤为肯出力、手不停，勤能补拙；俭为省着用、不糟蹋，俭以养廉；一开源一节流，合为治家之本。巧为心思灵、做得快；乖古义为违背、不顺，《说文》「乖，戾也」，与今之「乖巧」正相反，故巧对乖乃好字对坏字。榭读 xiè，为建在水边、底下架空的敞屋，四面开敞，专为临水观景；斋读 zhāi，为书房，山斋即山中读书之屋；水对山，游对学，一敞一静。冰桃出《拾遗记》，西王母降燕昭王，出冰桃、碧藕，为仙家清供，后世以冰桃代指珍品；雪藕谓藕切开白如雪；冰对雪皆冷皆白，桃对藕一果一蔬。漏箭为铜壶滴漏中所立之箭尺，壶水渐退，箭上刻度次第露出，视其露处以定时辰；更牌为更夫报更所挂之牌，一夜五更，更读 gēng；一在官署计时，一在街巷报时，皆今之钟表前身。五组对仗由德性及器物，由虚入实。落点：会出力，也会过日子。韵脚乖、斋、牌，同押九佳。',
