        description: '《笠翁对韵》十灰开篇，原文：「槐对柳，虎对骀。耸栋对高台。沈檀对梓柏，晚眺对晨妆。」五组对全是同类相对：树对树、兽对兽、屋对屋、木对木、时候对时候。槐树干高木硬，古人植于朝廷外以表三公之位，故「三槐」指大官；柳条细长垂水，折柳送别，故柳主情，一刚一柔。骀读 tái，为劣马，与「驽骀」同义，读 dài 则为「骀荡」；虎最有力、骀最无用，同类里挑两端。耸为高举，栋为屋之正梁，一根顶住全屋；台为垒土筑成之高坛，古时登高望远、祭天会盟。沈檀即沉香与檀香，沈通「沉」读 chén，沉香结于木中埋久乃香，檀香木细可雕佛像；梓木轻软不变形，可制器刻版，书印成曰「付梓」，柏耐寒常青，庙墓多植，前取香、后取用。晚眺为傍晚上高处远望，眺读 tiào；晨妆为晨起对镜梳妆，一晚一早、一外一内，最见工巧。落点：先归好类，再分高低。韵脚骀、台，同押十灰。',
