        description: '十灰续段，原文：「开雪障，启云扃。蟋蟀对螳螂。春暄资日气，秋冷借霜威。」障为屏障、阻隔，雪障谓厚雪堆成墙把路封死；扃读 jiōng，本义门闩，引申为门，云扃谓云中之门，指极高极险处；开、启皆打开之意，雪封的路要开，云锁的门要启。蟋蟀古名促织，北方呼蛐蛐，秋天一鸣，织者知天凉须赶工，故曰促织，《诗经·豳风·七月》有「十月蟋蟀入我床下」；螳螂前腿带刺如刀，「螳臂当车」出《庄子·人间世》，「螳螂捕蝉，黄雀在后」出《说苑》，一以鸣、一以刀，同类而活法不同。暄读 xuān，为暖和，「寒暄」即问冷问暖；资为凭借、依靠，本为财物本钱，日气为太阳热气，谓春之暖非自有，乃靠日晒。借为借来用，霜威为霜之威势，谓秋之冷亦非自有，乃借霜威。「资」与「借」意思近而分量异：资是本钱，常年之事；借是临时挪来，一阵之事。落点：暖是借来的，冷也是借来的；本事也是，得借着势才使得出来。',
