        description: '对韵段，原文：「南阮才郎差北富，东邻丑女效西颦。色艳北堂，草号忘忧忧甚事；香浓南国，花名含笑笑何人。」南阮北阮出《世说新语·任诞》：阮咸（字仲容）与阮籍居道南，诸阮居道北，北阮富而南阮贫；七月七日北阮盛晒纱罗锦绮，阮咸以竹竿挂大布犊鼻裈于中庭，人怪之，答曰「未能免俗，聊复尔耳」。差读chā，谓相差、比不上，贫富相形而才名自在。东邻丑女效西颦用《庄子·天运》「东施效颦」事：西施病心而颦，其里之丑人见而美之，归亦捧心而颦，富人见之闭门不出，贫人见之挈妻子而去；原文止称「其里之丑人」，「东施」是后人给的名字。所效者形，所不知者所以美，故庄子曰「彼知颦美，而不知颦之所以美」。北堂为古代居室东房后部，主妇所居，后借指母亲；忘忧草即萱草，《诗经·卫风·伯兮》「焉得谖草，言树之背」，谖草即萱草，背即北堂，故萱草又称母亲花。含笑为木兰科常绿灌木，产于岭南闽粤，花淡黄带紫边，半开时最香，状如抿嘴而笑，故有其名。末二句以反问收束：草名忘忧，究竟忘了什么忧；花名含笑，究竟笑的是谁。接682课，为《笠翁对韵》十一真第三段收尾。落点：境遇由天，忧笑由己。',
