        grade: '小学低中年级',
        description: '对韵段，原文：「词对赋，懒对勤。类聚对群分。鸾箫对凤笛，带草对香芸。」此段见《笠翁对韵》上卷十二文其二开篇，接686课「群僚仰对御炉薰」之后。词是起于唐五代、盛于宋的长短句，本配乐而歌，有词牌；赋是汉代大盛的文体，铺陈排比，介于诗文之间。词短赋长，一则言情一则铺采，都是文体，故能成对。懒对勤是反义相对，最浅也最正，如一面照人的镜子。类聚对群分出《周易·系辞上》「方以类聚，物以群分，吉凶生矣」，后世成语「物以类聚，人以群分」即由此来；类对群是同类相对，聚对分是一合一散。鸾是凤凰一类的神鸟，青色者称鸾，「鸾凤和鸣」谓夫妻相得；箫为竹制竖吹，相传萧史善吹箫娶弄玉，后乘鸾凤飞去。笛为竹制横吹，箫沉笛亮。鸾箫凤笛皆美称，一竖一横，故成对。带草即书带草，叶细长如带，相传汉郑玄（字康成）于高密山下讲学，山下多此草，人称「康成书带」，书院阶前常种。香芸即芸香，气味浓，古人藏书置书箱中驱虫，称「芸香辟蠹」，故书斋称「芸窗」、藏书处称「芸阁」。带对香是一形一嗅，草对芸是草木相对。全段四组，写的都是读书人的文事：文体、品性、典籍、乐器、书斋草木。落点：读书人的日子，件件有来历。',
