        description: '对韵段，原文：「相府珠帘垂白昼，边城画角动黄昏。枫叶半山，秋去烟霞堪倚杖；梨花满地，夜来风雨不开门。」此段见《笠翁对韵》十三元其二第三段，接697课「田种玉生根」之后，十三元其二至此完结。相府珠帘垂白昼：相府是宰相的府第，相读 xiàng；珠帘是珠串的帘子，垂白昼是白天也不卷起，写府第之深、日子之闲。边城画角动黄昏：边城是边塞城池，画角是军中彩绘的角，声哀厉，在城头报时警众，一动一吹，黄昏就有了声音。此句通行本作「动黄昏」，一作「对黄昏」，此处从通行本。枫叶半山，秋去烟霞堪倚杖：秋将尽时半山红叶，云霞正好；堪是可以、值得，拄杖看山是老年人的清福。梨花满地，夜来风雨不开门：化用刘方平《春怨》「寂寞空庭春欲晚，梨花满地不开门」，一夜风雨打落梨花，人不忍开门去看。对法：相府对边城一内一外，珠帘对画角一柔一刚，垂对动、白昼对黄昏；秋对春，堪倚杖对不开门。落点：同一天底下，日子不一样；一帘一城，一秋一春。',
