        path: 'lessons/700-jia-dui-guo-zhi-dui-an/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「家对国，治对安。地主对天官。坎男对离女，周诰对殷盘。」此段见《笠翁对韵》上卷十四寒开篇，接699课「早暮对寒暄」之后，十三元全章讲完，此为十四寒第一段。家对国：家是小的国，国是大的家；《大学》修身、齐家、治国、平天下，一级一级往上，孟子说「天下之本在国，国之本在家」。治对安：治读 zhì，是治理得好、天下太平，与乱相对；安是安定、安稳。治是用力做出来的，安是治成以后的踏实。地主对天官：地主是本地的主人、东道主，客人来了有个坐处，民间也指土地神；天官是《周礼》六官之首天官冢宰，总领百官、掌邦治，天上也有一套星官，《史记》有《天官书》，把星空分成三垣二十八宿。坎男对离女：八卦以乾坤为父母生六子，震长男、巽长女、坎中男、离中女、艮少男、兑少女；坎卦一阳陷于两阴之中，阳得中位，故为中男，属水；离卦一阴附于两阳之中，阴得中位，故为中女，属火。周诰对殷盘：周诰是《尚书·周书》里的诰命，如《大诰》《康诰》《酒诰》《召诰》《洛诰》，是周公、成王告诫臣民的话；殷盘是《尚书·商书》里的《盘庚》三篇，商王盘庚迁殷告谕臣民之辞；韩愈《进学解》「周诰殷盘，佶屈聱牙」，说这两路文章最难念。落点：家要治，国要安；地在脚下，天在头上；卦里水火相配，书里殷周相承。',
