        description: '对韵段，原文：「燕出帘边春寂寂，莺闻枕上漏珊珊。池柳烟飘，日夕郎归青琐闼；砌花雨过，月明人倚玉栏干。」此段见《笠翁对韵》上卷十四寒其一第三段，接701课「闲亭鹤影单」之后，十四寒其一至此完结。燕出帘边春寂寂：燕子从帘边飞出去，春天静得没一点声；燕是候鸟，春来秋去，古人以燕归为春信，檐下筑巢即有家；寂寂是叠字，一叠就慢下来。莺闻枕上漏珊珊：人还躺着，在枕上听见黄莺啼；漏是漏壶，古代计时之器，珊珊形容滴水声缓缓地一下一下。池柳烟飘，日夕郎归青琐闼：池边柳树新绿，远看像烟在飘，柳如烟是古诗常语；日夕是傍晚，郎是郎官，青琐闼是刻连琐纹涂青色的宫门，泛指宫廷官署。砌花雨过，月明人倚玉栏干：砌读 qì，是台阶，砌花即台阶边的花，别本一作阶花；一场雨刚过，月亮上来，人还倚着玉栏杆，写守候。对法：燕对莺、出对闻（一出门看见，一躺下听见）、帘边对枕上、寂寂对珊珊（叠字对叠字）；池柳对砌花、烟对雨、飘对过、日夕对月明、郎归对人倚、青琐闼对玉栏干。落点：一日之内，有出去也有回来；一处有着落，一处没着落。',
