        description: '对韵段，原文：「风凛凛，雪漫漫。手辣对心酸。莺莺对燕燕，小小对端端。」此段见《笠翁对韵》上卷十四寒其三第二段，接706课「虎踞对龙蟠」。风凛凛，雪漫漫：凛读 lǐn，本义寒冷，也带可敬畏之意，凛凛是说风冷得逼人，不是风大；漫读 màn，本义大水无边，引申为长、满、望不到头，漫漫是说雪下得天地一色，看不见路。手辣对心酸：辣和酸本是舌头上的味，转来说人情——手辣是手段狠、不留情，辣在手上是给别人受的；心酸是心里发苦想掉泪，酸在心里是自己受的。莺莺对燕燕：莺读 yīng，黄莺啼声婉转，叠作莺莺，出于唐元稹《会真记》崔莺莺，后为《西厢记》所本；燕燕出《诗经·邶风·燕燕》「燕燕于飞，差池其羽」，是卫庄姜送别之作。小小对端端：小小是南齐钱塘名妓苏小小，墓在西湖西泠桥畔，乐府《苏小小歌》「妾乘油壁车，郎骑青骢马」；端端旧注多以为唐时歌者，事迹已不可详考。四对全是叠字，前两个是鸟，后两个是人，由物及人，越对越近。落点：天有寒暖，人有甘苦，叠字里藏着一段春。',
