        description: '对韵段，原文：「林对坞，岭对峦。昼永对春闲。谋深对望重，任大对投艰。」此段见《笠翁对韵》上卷十五删其一开篇，接708课「老莱大孝」，十五删自此始。林是树聚成片，两木为林；坞读 wù，本指四面高、中间凹的山坳土堡，江南村落多叫坞，如杭州产龙井的梅家坞。岭读 lǐng 是山脊，连着的山脉，五岭、秦岭即是；峦读 luán 是小而尖的山，也泛指峰头。按平水韵，峦本属十四寒，与删韵为邻韵，诗韵中寒、删、先常通押，故编入十五删不违例。昼读 zhòu 是白天，永是长、久，昼永即天长，古人用它多带闲居意味；闲字门里有木，本义是栅栏，引申为空、无事，春闲即春日无事，心不催迫。谋是筹划，深是虑得远；望是名望，重是分量，望重来自德厚，即「德高望重」，一对里外：心里想得深，外面才站得重。任读 rèn 是责任，也作担当讲，任大即所负责任重大；投是投身、投入，艰读 jiān 是难，语出《尚书·大诰》「予造天役，遗大投艰于朕身」，是周公东征前对诸侯说的话。四对两景两人：前两对把眼界撑开、把心境放平，后两对说分量与肩膀。落点：眼要看得宽，心要闲得下，肩要扛得住。',
