        description: '对韵段，原文：「裙袅袅，佩珊珊。守塞对当关。密云千里合，新月一钩弯。」此段见《笠翁对韵》上卷十五删其一第二段，接709课「任大对投艰」。裙读 qún，是下裳，与裾（衣襟、衣袖）不同；袅袅读 niǎo niǎo，本义烟气缭绕上升，引申为细长柔软、摇曳不定，叠作袅袅就带出风一吹裙角跟着走的画面；佩是身上系的玉佩，珊珊读 shān shān 是玉石相击的声响，也形容步履从容，杜甫《郑驸马宅宴洞中》「时闻杂佩声珊珊」。二句一听一看，人未到声先到。塞读 sài，指边境险要处，边塞、要塞即是，不读 sāi、sè（sāi 是堵住，sè 是闭塞）；守塞是屯兵边上不让敌入。当读 dāng 是挡在、拦在，关是关隘，语本李白《蜀道难》「一夫当关，万夫莫开」。一远一近：守塞防一大片，当关守一条线。密是稠厚不透，云厚才叫密云，《周易·小畜》有「密云不雨」；合是合拢、聚到一处，千里说范围大。新月是月初刚露的一弯，又称蛾眉月、月牙；钩是挂物的弯钩，因弯月形似钩，借作量词，「一钩新月」与「一弯新月」同类。上句多、大、暗、合，下句少、小、亮、弯，天被压满又开一道缝。落点：身上有礼，眼里有山，心里有守。',
