        description: '对韵段，原文：「叔宝君臣皆纵逸，重华父母是嚚顽。名动帝畿，西蜀三苏来日下；壮游京洛，东吴二陆起云间。」此段见《笠翁对韵》上卷十五删其一第三段·收尾，接710课「新月一钩弯」，十五删其一至此讲完。叔宝是南朝陈末代皇帝陈后主陈叔宝，在位时不理政事，造临春、结绮、望仙三阁，与妃嫔文士宴游，作《玉树后庭花》，后人称为亡国之音；纵是放任，逸是安闲享乐，君臣皆纵逸，说的是上头一松、下面全散。重华是虞舜的名，读 chóng huá，不读 zhòng，《尚书·舜典》「曰若稽古帝舜，曰重华，协于帝」；嚚读 yín，愚昧顽固，《尚书·尧典》「父顽，母嚚，象傲」，舜母早亡，父亲、继母和弟弟象屡次要害他，舜躲过之后仍然孝顺友爱。帝畿读 jī，指京城及附近，畿是国都周围的地方；日下也是京城别称，古人把帝王比作太阳，帝王所在即日下，《世说新语》有陆云「云间陆士龙」与荀隐「日下荀鸣鹤」的对答。西蜀即今四川，三苏是眉山苏洵与子苏轼、苏辙，父子三人以文章名世；宋仁宗嘉祐年间进京，苏轼、苏辙同榜中进士，名声震动京师。京洛是洛阳，东周、东汉在此建都；壮游是怀抱壮志远行；二陆是西晋陆机、陆云兄弟，吴郡华亭人，陆逊之孙、陆抗之子，吴亡后从云间入洛，文章冠世；云间是今上海松江的古称。落点：环境可以由别人弄坏，品行只能由自己修好；有才还要敢走出去。',
