        description: '对韵段，原文：「歌宛转，貌婵娟。雪鼓对云笺。荒芦栖南雁，疏柳噪秋蝉。」此段见《笠翁对韵》下卷一先其一第二段·收尾，接715课「淡雨对覃烟」，一先其一至此讲完。宛转是声音高低回旋、不直不硬，也写作婉转；婵娟读 chán juān，本指姿态美好，多形容女子，孟郊《婵娟篇》说花、竹、人、月皆可婵娟，后来也代指月亮，苏轼「千里共婵娟」即是。歌是声、貌是形，一听一看，一句话里就站出一个人。雪鼓是鼓面蒙的皮硝得白净、其色如雪，一说是雪中擂鼓；笺读 jiān，是小幅的纸，供题诗写信，云笺即有云纹的彩笺，典出唐人韦陟封郇国公，用五彩笺写信，署名字如五朵云，人称郇公五云体。鼓是响器、是武，笺是纸笔、是文，雪对云都是天上的白。荒芦是野芦荡，加一个荒字便不是景是野地；栖读 qī，是鸟停歇；雁是候鸟，秋分后南飞，又有雁足传书的故事。疏是稀，柳叶落了大半枝子看得清；噪读 zào，是虫鸟群鸣，《礼记·月令》孟秋「寒蝉鸣」，柳永《雨霖铃》「寒蝉凄切」正是这一声。前一句静，后一句响，一静一响，秋就写完了。三句韵脚娟、笺、蝉同押 an，属下平一先。落点：写景要写得有声有色——看得见，也听得见。',
