        description: '对韵段，原文：「春九十，岁三千。钟鼓对管弦。入山逢宰相，无事即神仙。」此段见《笠翁对韵》下卷一先其三第二段，接721课「董杏对周莲」。春九十是一春九十天：春季三个月，每月三十日，合起来九十日，故以「九十」代整个春天，也称九十春光。岁三千是极言年寿之长：《庄子》说上古有大椿，以八千岁为春、八千岁为秋，民间又说王母蟠桃三千年一开花、三千年一结实，都是把寿数往长里说，不必落实。钟鼓是钟与鼓，庙堂与军中之乐，声洪大，属金石革；管弦是箫笛笙与琴瑟琵琶，声清细，属丝竹，故「丝竹」即管弦。入山逢宰相说的是南朝陶弘景，隐居句曲山即茅山，读书炼丹，梁武帝每有大事便派人入山咨询，时人称为山中宰相，所以入山反而遇见宰相。无事即神仙是说心里没有俗务缠身，人就是神仙，俗语「无事小神仙」正是此意。三句韵脚千、弦、仙，同属下平一先。落点：春有九十日，人寿三千年，都不如心里无事——这一段写的是自在。',
