        description: '对韵段，原文：「霞映武陵桃淡淡，烟荒隋堤柳绵绵。七碗月团，啜罢清风生腋下；三杯云液，饮余红雨晕腮边。」此段见《笠翁对韵》下卷一先其三收尾，接722课「无事即神仙」，一先其三到此完结。武陵桃花出陶渊明《桃花源记》：武陵人捕鱼为业，缘溪行，忽逢桃花林，夹岸数百步，中无杂树，故武陵桃花成了世外之境的代称，淡淡是花色浅淡不浓。隋堤是隋炀帝开通济渠时沿堤植柳，后世称隋堤柳，烟荒是说烟雾里一片荒凉，绵绵是连绵不断，白居易《隋堤柳》「岁久年深尽衰朽」正是此意。七碗月团说的是卢仝《走笔谢孟谏议寄新茶》：一碗喉吻润，两碗破孤闷，三碗搜枯肠……七碗吃不得也，唯觉两腋习习清风生；月团是团饼茶，唐宋茶多压成饼，啜读 chuò，是小口喝。三杯云液说的是酒，云液是美酒的雅称，饮余即饮罢，红雨是脸上泛起的红晕，晕读 yùn。四句韵脚绵、边，同属下平一先。落点：一段好景、一碗好茶、一杯好酒，都是把日子过出滋味来。',
