        description: '对韵段，原文：「山寂寂，水迢迢。雪岭对云椒。醉吟太白句，狂草子明毫。」四组对子分三层：山水、山、诗书。寂是安静无声，叠成「寂寂」静得更沉；迢是路远水长，《古诗十九首》「迢迢牵牛星，皎皎河汉女」；叠字的作用是拉长，单说「山寂」淡，说「山寂寂」就有了回声。岭是山脉高处，积雪终年不化，远看一道白线；「椒」在古书里指山尖，「山椒」即山顶，「云椒」就是钻进云里的山顶，一横一尖，同是山的两副面孔。太白是李白的字，号青莲居士，贺知章一见《蜀道难》称他「谪仙人」；杜甫《饮中八仙歌》「李白一斗诗百篇，长安市上酒家眠」「天子呼来不上船，自称臣是酒中仙」。狂草是草书里最放得开的一种，一笔连着一笔，唐代张旭、怀素最著名，人称「颠张醉素」；毫本指细毛，羊毫软、狼毫硬、紫毫尖，都是毛笔，「挥毫」即提笔，「毫厘」的毫是引申的一点点。「雪岭对云潭」见于《声律启蒙·十三覃》，本段作「云椒」，更贴山尖本义；「醉吟太白句，狂草子明毫」通行本查不到，为对课对字，「子明」指善草书的书家，说法不一，课件不指实人。韵：迢、椒属下平二萧，毫属下平四豪。落点：静下来才看得远；醉里有真诗，狂中有法度。',
