        description: '对韵段，原文：「龙夭矫，虎咆哮。北学对东胶。筑台须垒土，成屋必诛茅。」四组对子分三层：物、学、事。夭矫是屈伸自如、盘曲飞腾的样子，写龙身的曲伸，司马相如《上林赋》「夭蟜枝格，偃蹇杪颠」即此意；咆哮是连吼带喘的怒声，《楚辞·招隐士》「虎豹斗兮熊罴咆」。《说文》「龙，鳞虫之长，能幽能明，能细能巨」「虎，山兽之君」，《易·乾卦》「云从龙，风从虎」，龙虎本就配成一对，一写形一写声。东胶是周代大学，在王宫东面，《礼记·王制》「周人养国老于东胶，养庶老于虞庠」；北学是北面的学宫，《大戴礼记·保傅》记天子入学有东学、西学、南学、北学；北对东是方位对，学对胶是同义对。筑台须垒土，古人筑台不用砖，用土层层夯实，化用《老子》「九层之台，起于累土」；诛是剪除、刈割，诛茅即割茅草苫屋，《诗经·豳风·七月》「昼尔于茅，宵尔索绹」，杜甫《寄题江外草堂》「诛茅初一亩」；须对必，两个虚字都硬。韵：哮、胶、茅三个韵脚同收 -āo 音，属下平三肴，一韵到底，与第 733 课同韵。落点：龙虎练气势，胶庠讲来历，垒土诛茅说的是做事——再高的台子也起于一筐土。',
