        grade: '小学低中年级',
        description: '对韵段，原文：「何妥难，子云嘲。楚甸对商郊。五音惟耳听，万虑在心包。」三组对子分三层：两个古人、两个地方、外与内。何妥字栖凤，隋代人，西域何国后裔，精经学、尤通音律，隋文帝时为国子博士；开皇年间议雅乐，何妥与苏夔往复辩难，主张黄钟一宫，不肯相下；「难」读 nàn，是诘难、辩驳，不是「困难」的难。扬雄字子云，西汉蜀郡成都人，口吃不能剧谈，好深湛之思，作《太玄》《法言》《方言》；有人嘲他官位不显、著作无用，说《太玄》如「玄尚白」，他设「客嘲扬子」一问一答，作《解嘲》，名为解嘲实为自解。甸是王城郊外经过整理的田地，《周礼》有邦甸、甸师；楚甸是楚地原野，南方水泽草木深长；商郊是商都郊外，《尚书·牧誓》「王朝至于商郊牧野」，武王伐纣在此誓师，《诗经·大雅·大明》「牧野洋洋，檀车煌煌」；楚对商是国名对，甸对郊是野地对，一南一北。五音是宫商角徵羽，《孟子·离娄上》「不以六律，不能正五音」；耳是听官，《庄子·人间世》「无听之以耳而听之以心」；万虑是种种念头，《孟子·告子上》「心之官则思」，心包即心所包藏，故万虑在心包；五音对万虑是外对内的物对，耳对心是感官对心思，一外一内。韵：嘲、郊、包三个韵脚同收 -āo 音，属下平三肴，与第 733—736 课一韵到底。落点：辩难辩的是理，解嘲解的是心；五音听清只需一只耳朵，万虑放下却要一辈子。',
