        grade: '小学低中年级',
        description: '对韵段，原文：「葛被汤征因仇饷，楚遭齐伐责包茅。高矣若天，洵是圣人大道；淡而如水，实为君子神交。」四句分两层：两句史事、两句道理。葛是夏朝诸侯国，汤居亳，与葛为邻；葛伯放而不祀，推说没有牛羊粮食，汤送牛羊粮食，他吃了仍不祭；汤又派亳众代耕，老弱往田里送饭，葛伯带人拦路夺酒食黍稻，不给就杀，一个送饭童子被杀。《尚书》记作「葛伯仇饷」，汤为这个孩子出兵，四海之内说「非富天下也，为匹夫匹妇复仇也」；仇饷是与送饭的人为仇，饷读 xiǎng，是馈食不是军饷。鲁僖公四年齐桓公以诸侯之师侵蔡，蔡溃遂伐楚，楚使问「风马牛不相及」，管仲答「尔贡包茅不入，王祭不共，无以缩酒，寡人是征」，又问昭王南征不复；包茅是束成把的菁茅，祭祀时浇酒渗下叫缩酒，楚人只认第一条，说「贡之不入，寡君之罪也」，盟于召陵而兵退。高矣若天出《孟子·尽心上》，公孙丑叹「道则高矣美矣，宜若登天然，似不可及也」，孟子答「大匠不为拙工改废绳墨，羿不为拙射变其彀率」「君子引而不发，跃如也」；洵读 xún，是诚然、确实。淡而如水出《庄子·山木》「君子之交淡若水，小人之交甘若醴」，又「君子淡以亲，小人甘以绝」；神交是心意相通，王徽之雪夜访戴逵，到门不入，说「兴尽而返，何必见戴」；薛仁贵未遇时受王茂生接济，封平辽王后只收他两坛清水，当众饮下。韵：茅、交两个韵脚同收 -āo 音，属下平三肴，与第 733—737 课一韵到底。落点：该争的名分要争到底，不该争的交情要淡到底；道要往上够，交要往淡处守。',
