        description: '对韵段，原文：「牛对马，犬对猫。旨酒对嘉肴。桃红对柳绿，竹叶对松梢。」四组对子由粗到细：兽对兽、饮对食、色对色、部位对部位。牛马犬猫都在六畜之内，《三字经》「马牛羊，鸡犬豕，此六畜，人所饲」；牛慢而稳、低头拉犁耕田，马快而烈、扬蹄征战；犬守夜看门、鼻子耳朵都灵，猫捕鼠、走路没有声音，一大一小各有差事。旨读 zhǐ，本义是味美不是「旨意」，《诗经·小雅·鹿鸣》「我有旨酒，以燕乐嘉宾之心」；嘉肴出《礼记·学记》「虽有嘉肴，弗食，不知其旨也」，肴读 yáo 不读 xiáo，本指鱼肉做的荤菜。桃红柳绿是颜色对，王维《田园乐》「桃红复含宿雨，柳绿更带朝烟」，红对绿一暖一冷，桃对柳是树名对，单说红对绿是空的，加个物才落地。竹叶对松梢，竹对松是树对树，叶对梢是部位对，叶在面上铺开、梢在尖上竖起，一横一竖；梢读 shāo，是树梢、末梢；「竹叶青」是酒名，此处取字面。韵：猫、肴、梢三个韵脚同收 -āo 音，属下平三肴，与第 733—738 课一韵到底。此段为三肴第三段开篇，往下接「藜杖叟，布衣樵，北野对东郊」。落点：身边的东西认得清，笔下才写得活；牛马犬猫、桃红柳绿，都是农家日见之物，功夫不在词多，在看得细。',
