        description: '对韵段，原文：「藜杖叟，布衣樵。北野对东郊。白驹形皎皎，黄鸟语交交。」四组对子：人对人、地对地、色对声。藜读 lí，一年生野草，嫩叶可吃，茎老又硬又轻，割下做拐杖正合适，藜杖是最素的一根杖；叟读 sǒu，是老翁。布衣是麻布衣裳，古时平民才穿，《出师表》「臣本布衣，躬耕于南阳」诸葛亮也这样自称，布衣樵就是穿粗布的打柴人。藜杖对布衣，一个是手里的，一个是身上的；叟对樵，一个是拄杖闲行的老翁，一个是上山打柴的樵夫，同是平民老者，一闲一劳。北野对东郊：北对东是方位对，野对郊是地类对，《尔雅》「邑外谓之郊，郊外谓之牧，牧外谓之野」，郊近野远，一近一远正好成对。白驹形皎皎出《诗经·小雅·白驹》「皎皎白驹，在彼空谷」，驹读 jū 本指两岁以下幼马，皎读 jiǎo 本义月光白，叠成皎皎比单说「白」更亮；此处的白驹指眼中所见的白马，与《庄子》「白驹过隙」喻时光不同。黄鸟语交交出《诗经·秦风·黄鸟》「交交黄鸟，止于棘」，交交是鸟鸣拟声，一声递一声。对法四层：白对黄是颜色对、驹对鸟是兽对禽、形对语是色对声、皎皎对交交是叠字对叠字，一眼一耳最工。韵：樵 qiáo、郊 jiāo、交 jiāo 三个韵脚同收 -āo 音，属下平三肴，接第 739 课一韵到底；叟 sǒu、皎 jiǎo 为出句末字不必押韵。位置：三肴第三段第二层，后接「花圃春残无客到」。落点：最平常的景——一根草杖、一件粗衣、一片野地、一匹马、一只鸟——看得细、听得真，凑在一起就亮堂。',
