        grade: '小学低中年级',
        description: '对韵段，原文：「花圃春残无客到，柴门夜永有僧敲。墙畔佳人，飘扬竞把秋千舞；楼前公子，笑语争将蹴踘抛。」前联一无一有：花圃春尽、花瓣落尽，没人再来赏花；柴门夜长，偏有僧人来敲门，一寂一响。圃读 pǔ，本指种菜种花的园地；柴门是荆条柴木扎的门，寒素之家；永是长，夜永即夜长，越静越显敲声。有僧敲用贾岛《题李凝幽居》「僧敲月下门」的典：他先写作「僧推月下门」，骑驴比划推敲之手势，撞进韩愈仪仗，韩愈定「敲」更好——夜里静，敲门才有声，推敲一词由此而来。后联两组扇面对：墙畔佳人对楼前公子是位置加人物，飘扬对笑语是动姿对声音，竞把对争将是虚字对，秋千舞对蹴踘抛是游戏对游戏；寒食清明最兴荡秋千，李清照「蹴罢秋千，起来慵整纤纤手」可证；蹴踘读 cù jū，蹴是踢、踘是皮缝充气的球，《史记·苏秦列传》「六博蹋鞠者」可见战国已盛，与今日足球一路。韵：敲 qiāo、抛 pāo 两个韵脚同收 -āo 音，属下平三肴，接第 740 课，三肴第三段至此完结。落点：写景要会配——空对满、静对闹、无人对有人；贾岛斟酌「推」「敲」，一字之差，境界两样。',
