        description: '对韵段，原文：「微对巨，少对多。直干对平柯。蜂媒对蝶使，雨笠对烟蓑。」四组对子由字面到活物。微读 wēi 本义隐蔽细小，巨是巨大；少与多是数量相反——两对反义，连实物都不用，光字面就成对，是对韵的底子功。直干对平柯：干读 gàn 指树干（读 gān 才是干燥、干戈），柯读 kē 本义斧柄，《诗经·豳风·伐柯》「伐柯如何？匪斧不克」，引申为枝茎；直对平是形状对、干对柯是主干对枝条，一竖一横树就立住。蜂媒对蝶使：蜂采蜜带走花粉、蝶一停一落像递话，古人比作媒人与信使，元曲有「蜂媒蝶使」的惯语，是虫对虫而用拟人，物一说成人句子就有情。雨笠对烟蓑：笠读 lì 是竹篾编的宽边帽遮雨遮日，蓑读 suō 是蓑草编的雨衣，张志和《渔歌子》「青箬笠，绿蓑衣，斜风细雨不须归」、柳宗元《江雪》「孤舟蓑笠翁，独钓寒江雪」都是这一身；雨对烟是天气对，笠对蓑是头对身。韵：多 duō、柯 kē、蓑 suō 三个韵脚同属下平五歌，此课为五歌第一段开篇，前接三肴第 741 课。落点：先对字、再对物，大小多少是死字，蜂蝶笠蓑是活物；字要对得稳，物要对得活。',
