        description: '对韵段，原文：「眉淡扫，面微酡。妙舞对清歌。轻衫裁夏葛，薄袂剪春罗。」四组对子由容色到歌舞再到衣裳。眉淡扫即淡淡描眉，扫是画，张祜《集灵台》「却嫌脂粉污颜色，淡扫蛾眉朝至尊」写虢国夫人只描眉不擦粉；面微酡，酡读 tuó 本指饮酒后脸泛红，《楚辞·招魂》「美人既醉，朱颜酡些」，「微」字见分寸，是薄薄一层红不是通红。妙舞对清歌：妙与清都是赞词，舞是身段、歌是声音，一个用眼看一个用耳听；《列子·汤问》记韩娥唱歌「余音绕梁欐，三日不绝」。轻衫裁夏葛、薄袂剪春罗：衫是单衣、袂 mèi 是衣袖，裁与剪同为做衣工序；葛读 gé 是藤本植物，茎皮纤维织布夏日透气，《诗经·周南·葛覃》「葛之覃兮，施于中谷」；罗是带孔的轻薄丝织品，宜于春天。对法：眉对面是部位对、淡扫对微酡是淡妆对红晕；妙对清、舞对歌；轻衫对薄袂是衣对袖、裁对剪、夏葛对春罗是季节对料子（一布一丝、一凉一暖）。韵：酡 tuó、歌 gē、罗 luó 三个韵脚同属下平五歌，接第 742 课。落点：全段没有一个「美」字，只写眉上一笔、脸上一层、袖口一寸，人却清清楚楚站在那里——写人抓得准，比说得满更强。',
