        subtitle: '五歌对课',
        path: 'lessons/745-ci-dui-shan/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「慈对善，虐对苛。缥缈对婆娑。长杨对细柳，嫩蕊对寒莎。」四组对子由待人之德到写景之词再到草木。慈是上对下的亲爱，《说文》「慈，爱也」，父母对子女最典型；善是心地的正、做出来的好；虐读 nüè，是残暴，《说文》「虐，残也」；苛读 kē，本义是小草，《说文》「苛，小草也」，草细碎密集引申为政令繁细、待人严苛——一个狠在手上，一个狠在嘴上。前两句近义成对而上下正反相照：上句都暖，下句都冷。缥缈 piāo miǎo 是隐约若有若无，白居易《长恨歌》「忽闻海上有仙山，山在虚无缥缈间」；婆娑 pó suō 是枝叶扶疏、舞动的样子，《诗经·陈风·东门之枌》「婆娑其下」；两个都是联绵词，拆开单字就没意思，正好两两相对，一虚一实、一静一动。长杨是汉长杨宫，在上林苑中，因宫有长杨树得名，汉成帝曾在此校猎，扬雄作《长杨赋》劝谏；细柳是周亚夫的细柳营，《史记·绛侯周勃世家》记文帝劳军，先驱不得入，曰「军中闻将军令，不闻天子之诏」，文帝叹「此真将军矣」；长对细是形状对、杨对柳是同类木，底下更是宫对营——一处文治一处武备，一句两义。嫩蕊是初生花心，嫩是柔软经不起风；寒莎是莎草，莎读 suō，多年生，地下有块茎即香附子，秋深不枯故称寒莎；嫩对寒是质性对、蕊对莎是花对草，一娇一韧。韵：苛 kē、娑 suō、莎 suō 三个韵脚同属下平五歌，此课为五歌第二段开篇，前接五歌第一段收尾第 744 课。落点：慈与善是暖的、虐与苛是冷的，待人要暖、管事别苛；嫩蕊怕寒、寒莎耐寒，草木各有各的活法。',
