        grade: '小学低中年级',
        description: '对韵段，原文：「追风马，挽日戈。玉液对金波。紫诏衔丹凤，黄庭换白鹅。」三组对子由夸口到酒色再到文事。追风是骏马名，相传秦始皇有名马七匹，其一即追风，另有白兔、蹑景、奔电、飞翮、铜爵、晨凫，都是快得看不见的意思；挽读 wǎn 是拉拽，戈是长柄兵器，挽日戈出《淮南子·览冥训》——鲁阳公与韩交战，战酣日暮，援戈一挥，日为之退三舍，故称能拉回落日；追风对挽日都是人做不成的大话，气势相等，马对戈一活物一器物，三字一顿最有力。玉液是美酒，色清如玉，道家又指口中津液；金波多写月光映水如碎金浮动，也用作酒名；玉对金是色、液对波是形，一句写杯中一句写天上。紫诏是紫泥封缄加玺的诏书，汉制如此，故诏书称紫诏；衔读 xián 是含，《邺中记》记后赵石季龙于观上作木凤，五色纸诏置于凤口，缒绳而下，称凤诏；紫诏是文书之贵，衔凤是颁下之仪。黄庭换白鹅是王羲之写经换鹅，《晋书·王羲之传》记山阴道士养好鹅，羲之求买，道士请写经相赠，写毕笼鹅而归，原文作《道德经》，李白《送贺宾客归越》「山阴道士如相见，应写黄庭换白鹅」始称《黄庭》；紫对黄、丹对白是两组颜色，诏对庭、衔对换、凤对鹅是三对实字，四字之内两色两禽，是全书最工的对法之一。韵：戈 gē、波 bō、鹅 é 三个韵脚同属下平五歌，此课接第二段开篇第 745 课，五歌第二段尚未收尾。落点：追风挽日是人想胜天，换鹅写经是人只图自己高兴；本事可以往大处想，心要往闲处放。',
