        grade: '小学低中年级',
        description: '对韵段，原文：「画阁江城梅作调，兰舟野渡竹为歌。门外雪飞，错认空中飘柳絮；岩边瀑响，误疑天半落银河。」前联写两处声音。画阁是彩绘楼阁，江城是临江之城，李白《与史郎中钦听黄鹤楼上吹笛》「黄鹤楼中吹玉笛，江城五月落梅花」即指武昌；调读 diào 是曲调，《梅花落》为汉横吹曲名，多用笛吹，曲中说梅花片片落下，故「梅作调」不是真有梅花，是笛声里有梅花。兰舟本指木兰木所造之船，后泛指华美之船，柳永《雨霖铃》「兰舟催发」；野渡是荒野渡口，韦应物《滁州西涧》「野渡无人舟自横」；竹可指竹笛竹箫，也可指《竹枝》歌——巴渝民歌，刘禹锡有《竹枝词》；上句是曲牌，下句也是曲，梅对竹、调对歌最对得上。对法：画阁对兰舟是精美之物，江城对野渡是一热闹一荒僻。后联两回认错。门外雪飞，从屋里往外看，雪大片落得慢才看得像，用《世说新语·言语》谢道韫事——谢太傅雪日问「白雪纷纷何所似」，兄子说「撒盐空中差可拟」，兄女说「未若柳絮因风起」，公大笑乐，遂有咏絮才之称。岩边瀑响先闻其声，瀑读 pù，化用李白《望庐山瀑布》「飞流直下三千尺，疑是银河落九天」，改作「天半」比九天更近更像眼前。对法：门外对岩边、雪飞对瀑响是一见一闻、错认对误疑是同一副心思、飘柳絮对落银河是两句比方，一轻一重；雪与瀑都白都往下落，故能相对。韵：歌 gē 属下平五歌，为本段最后一个韵脚，调读 diào 去声不入韵；全段韵脚苛、娑、莎、戈、波、鹅、歌 同属五歌，五歌第二段至此完结，接 746 课。落点：眼睛会看错、耳朵会听错，可这错处正是诗——雪像柳絮才轻，瀑像银河才壮。',
