        description: '对韵段，原文：「松对竹，荇对荷。薜荔对藤萝。梯云对步月，樵唱对渔歌。」四组对子由草木到攀附再到高远与山野人声。松经冬不凋，《论语·子罕》「岁寒，然后知松柏之后凋也」；竹中空有节、雪压不断，与松梅并称岁寒三友——松对竹是同一种硬性子。荇读 xìng，荇菜，叶圆而小浮在水面、茎在水下，可采食，《诗经·周南·关雎》「参差荇菜，左右流之」开篇即写采它；荷即莲，有花有香——荇对荷是两样水生，一山一水、一刚一柔。薜荔读 bì lì，桑科攀缘藤本，附墙缘树而生，果实洗粉可做凉食（凉粉果），屈原《九歌·山鬼》「被薜荔兮带女萝」；藤萝是紫藤一类藤本，茎长而软，必缠绕他物才立得住，李白《紫藤树》写之——两者都靠攀附，但一横铺满壁、一直上缠枝，姿态相反。梯云是以云为梯，梯本名词作动词用，喻青云直上；步月是月下行步，古人又用「蟾宫折桂」「步月登科」祝科举得意，故这一联既是高远景象又带吉利彩头；梯对步是动作对、云对月是天象对，一虚一实。樵读 qiáo 是打柴人，樵唱是随口山歌，王维《桃源行》「樵客初传汉姓名」；渔歌是船上的调子，柳宗元《渔翁》「烟销日出不见人，欸乃一声山水绿」；樵对渔是伐木对捕鱼、山中水上各有一声，唱对歌同义换字以免重复。韵：荷 hé、萝 luó、歌 gē 三个韵脚同属下平五歌，此课为五歌第三段开篇，前接第二段收尾第 747 课。落点：松竹靠自己的骨气站住，荇荷靠水托着，薜荔藤萝靠墙靠树，樵夫渔人各安其业——认清自己靠什么，路就不慌。',
