        description: '对韵段，原文：「升鼎雉，听经鹅。北海对东坡。吴郎哀废宅，邵子乐行窝。」两桩禽鸟故事加两处人间居所。升鼎雉出《尚书·高宗肜日》：商王武丁祭成汤，有野鸡飞上鼎耳鸣叫，鼎是三足两耳的祭器，鸟上重器古人视为天示警戒，祖己借此劝王修德，武丁听劝而殷道复兴，是为武丁中兴；雉读 zhì 即野鸡，雊读 gòu 是雉鸣——这不是凶兆，是老天爷提醒他改过。听经鹅是佛门旧记：僧人诵经，白鹅走到阶下侧耳倾听，久而不去，用意在「感」字——禽鸟尚能为经声所动，何况是人，与「生公说法，顽石点头」是一路意思。北海指孔融，字文举，汉末任北海相，世称孔北海，建安七子之首，「座上客常满，樽中酒不空」，后因言语触怒曹操被杀；东坡指苏轼，贬黄州后俸禄断绝，在城东山坡开荒，自号东坡居士，在此写出前后《赤壁赋》与《念奴娇·赤壁怀古》——二者都以地名代人，一个因做官得地、一个因落难得地。吴郎指晚唐吴融，字子华，有《废宅》诗：「风飘碧瓦雨摧垣」写瓦揭墙塌，「放鱼池涸蛙争聚，栖燕梁空雀自喧」写人一走先来的都是不相干的东西，末以「咸阳一火」收束，由一家兴废见天下兴亡，所以「哀」不是哀房子是哀兴亡。邵子指北宋邵雍，字尧夫，谥康节，初到洛阳屋子漏雨、打柴煮饭，后司马光等人凑钱为他买宅，取名「安乐窝」，自号安乐先生；《宋史》记好事者照安乐窝的样子另建一屋等他来住，名曰「行窝」——行是行走，走到哪儿都有个窝。对法：雉对鹅是鸟对鸟，升对听是动作，鼎对经是器物对典籍；吴郎对邵子是姓加称谓，哀对乐为反义，废宅对行窝为居所，一唐一宋、一悲一喜，最见工整。韵：鹅 é、坡 pō、窝 wō 三个韵脚同属下平五歌，此课为五歌第三段第二课，前接第 748 课。落点：同样是几间屋子，吴融走进去看见的是废墟，邵雍住下来过成了安乐窝——屋子是死的，人是活的，日子过成什么样，多半看住的人怎么想。',
