        grade: '小学低中年级',
        description: '对韵段，原文：「丽水良金皆待冶，昆山美玉总须磨。雨过皇州，琉璃色灿华清瓦；风来帝苑，荷芰香飘太液波。」四句分两半：前两句说材料要加工，后两句说景致靠天成。丽水即金沙江，古称丽水，江边沙里淘得出金屑，云南丽江因它得名；昆山即昆仑山，产和田玉；两句并出《千字文》「金生丽水，玉出昆冈」。良金是好金，冶读 yě 是熔炼，《说文》「冶，销也」，淘出的沙金夹着砂石须入炉去杂才成器，《周礼·考工记》讲「金有六齐」，铜锡配多少皆有定数；《礼记·学记》「玉不琢，不成器」，《三字经》接着「人不学，不知义」，《诗经·卫风·淇奥》「如切如磋，如琢如磨」，毛传谓治骨曰切、治象曰磋、治玉曰琢、治石曰磨，本说君子修养——金靠火、玉靠手，一刚一柔两种工夫。皇州即京城，谢朓「宛洛佳遨游，春色满皇州」；琉璃瓦挂釉，雨洗之后碧黄皆亮，唐代宫殿已用、明清方铺满；华清即华清宫，在骊山，唐玄宗开元间建温泉宫，天宝六载改名，白居易《长恨歌》「春寒赐浴华清池」、杜牧《过华清宫》「长安回望绣成堆」皆写此地。帝苑是皇家苑囿，汉上林苑、唐禁苑；荷是荷花，芰读 jì 是菱，屈原《离骚》「制芰荷以为衣兮，集芙蓉以为裳」；太液是皇家池沼通名，汉建章宫北有太液池、唐大明宫北亦有（又名蓬莱池），元明清三代之太液池即今中南海与北海。对法：丽水对昆山地名对，良金对美玉物对，皆对总虚字对，待冶对须磨动宾对；雨过对风来，皇州对帝苑，琉璃对荷芰，色灿对香飘为视对嗅，华清瓦对太液波为一宫一池——色对香、灿对飘、瓦对波，一句一感不相重复，最见巧思。韵：磨 mó、波 bō 两个韵脚同属下平五歌，此课为五歌第三段收尾，第三段至此完，前接第 749 课。落点：材料是老天给的，工夫是自己下的，机缘是等来的——三样凑齐，才有那一片瓦光、一池荷香，急不得也懒不得。',
