        grade: '小学低中年级',
        description: '对韵段，原文：「笼对槛，巢对窝。及第对登科。冰清对玉润，地利对人和。」五组对子由住处说到名分再说到人品，一路由外入内。笼读 lóng，竹木编的鸟笼；槛读 jiàn，圈野兽的栅栏，《淮南子·主术训》「养虎豹犀象者，为之圈槛」，笼小槛大、一精巧一粗重，都夺了飞禽走兽的自由。巢是鸟在树上筑的，《说文》「鸟在木上曰巢」，上古有巢氏教人构木为巢；《诗经·召南·鹊巢》「维鹊有巢，维鸠居之」即「鸠占鹊巢」所本；窝是口语，鸟窝兽窝被窝皆可，巢雅窝俗，一字之差气象不同。及第是考中、名字上了榜，第即榜上次第，落榜叫落第；唐代取士分明经进士等科，考中即登科，进士科最重，俗语「三十老明经，五十少进士」；孟郊四十六岁才中，作《登科后》「春风得意马蹄疾，一日看尽长安花」；两词一事，换字避复，是本事不是凑。冰清玉润出《晋书·卫玠传》：卫玠娶乐广之女，时人谓「妇公冰清，女婿玉润」，妇公即岳父，故本为夸一对翁婿；卫玠风神秀异，出门被人围观，《世说新语》有「看杀卫玠」之说，后世遂泛用人品高洁、器物晶莹。地利人和出《孟子·公孙丑下》「天时不如地利，地利不如人和」，地利是山川险要与土地肥饶（金城汤池之说），人和是人心齐一，三样里孟子最重人和。对法：笼对槛、巢对窝是同门类相对，前一组是关、后一组是住；及第对登科是同事换字；冰对玉是物、清对润是性，冰是冷的透、玉是温的润；地利对人和为成语相对，一地一人、一外一内。韵：窝 wō、科 kē、和 hé 三个韵脚同属下平五歌，此课为五歌第四段开篇，前接第 750 课。落点：关得住的是笼槛，安得住的是巢窝；挣得来的是科名，修得来的是冰玉；争得到的是地利，拢得住的是人心——前面几样都靠外头，最后一样全在自己。',
