        grade: '小学低中年级',
        description: '对韵段，原文：「韩擒虎，荣驾鹅。青女对素娥。破头朱泚笏，折齿谢鲲梭。」四组对子，两组古人、一组神女、两句史事，排到末句落在人身上。韩擒虎字子通，隋初名将，开皇九年率兵夜渡长江直入建康，俘陈后主陈叔宝，南朝至此终；《隋书》记其病重曰「生为上柱国，死作阎罗王，斯亦足矣」，民间遂传为阎王之一。荣驾鹅即鲁大夫荣成伯，名驾鹅，《左传·襄公二十九年》鲁襄公自楚返，闻季武子取卞，赌气不欲入国，荣成伯赋《诗经·邶风·式微》「式微式微，胡不归」，公乃归；一以力取国，一以言归君。青女是主霜雪的天神，《淮南子·天文训》「青女乃出，以降霜雪」，高诱注「青女，天神，青霄玉女，主霜雪也」；素娥即嫦娥，月色白故称素，谢庄《月赋》「集素娥于后庭」；李商隐《霜月》「青女素娥俱耐冷，月中霜里斗婵娟」为此联所本。破头朱泚笏：建中四年泾原兵变，朱泚被乱兵拥立，国号大秦，攻入长安，唐德宗奔奉天，百官多受伪职；司农卿段秀实被召议事，夺象笏击其面门，中额血溅，大呼「我不同反，何不杀我」，遂遇害，后赠太尉谥忠烈；笏读 hù，大臣朝会所执手板，手里无刀便以手板为刀。折齿谢鲲梭：《晋书·谢鲲传》谢鲲字幼舆，谢安伯父，好老庄任自然，为江左八达之一；邻有高氏女，鲲尝挑之，女投梭折其两齿，时人语「任达不已，幼舆折齿」，鲲傲然长啸曰「犹不废我啸歌」。对法：擒对驾是动、虎对鹅是物，一猛一驯；青对素是色、女对娥是人；破头对折齿是伤、朱泚对谢鲲是人名、笏对梭是器，五字一句字字同位，最见压缩功夫。韵：鹅 é、娥 é、梭 suō 三个韵脚同属下平五歌，此课为五歌第四段第二课，前接第 751 课。落点：擒虎靠力、驾鹅靠言，力气与言语都得有；青女主霜、素娥主月，清冷的美要耐得住；笏与梭同是伤人的器物，一个守住了节，一个丢掉了脸——器物本身不分善恶，看是谁在使。',
