        path: 'lessons/753-liu-ke-jiu-bei/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「留客酒杯应恨少，动人诗句不须多。绿野凝烟，但听村前双牧笛；沧江积雪，惟看滩上一渔蓑。」前两句说人情，比一个多少；后两句写景，比一个听看，都是分寸。留客要酒，一杯一杯地斟，话就长了、天就晚了，故只嫌杯少；杜甫《客至》「樽酒家贫只旧醅」，家贫只有浊酒也照样请客。「应」是应该，「恨」不是怨恨而是遗憾、嫌不够，同俗语「酒逢知己千杯少」，恨的不是酒少是天黑得太早。动人诗句不须多，不在辞藻热闹，在说中别人说不出的一句：白居易写诗先念给老妇人听，听不懂就改；张继一生无名，《枫桥夜泊》只二十八字而寒山寺钟声响逾千年；贾岛「两句三年得，一吟双泪流」，好句是磨出来的不是堆出来的。应恨少与不须多虚字相对而一反一正——酒要加法，诗要减法，同一个多字两样用法，是这一联的机关。绿野凝烟：绿野是田野，凝烟是暮气聚而不散，烟一起远景全糊，眼睛不管用，才轮得到耳朵；但闻是只听见，「但」当「只」讲；双牧笛是两支笛子一高一低隔埂应答，村子就活了。沧江积雪：沧江是青苍色的江水，雪一落江岸天地全白，白到极处山径人迹俱无，只剩滩上一件蓑衣；惟看是只看见，「惟」也当「只」讲，与上句的「但」正好成对；蓑是草编雨衣，以物代人，省字而味长，如柳宗元「孤舟蓑笠翁」。对法：留客对动人皆动宾，酒杯对诗句一物一文，绿野对沧江色对色、野对江，凝烟对积雪同是遮景之物一软一硬，但听对惟看是耳对眼，双对一是一双一单、热闹对孤冷。韵：多 duō、蓑 suō 同属下平五歌，此课为五歌第四段收尾，前接第 752 课。落点：待客要厚，落笔要精；看不全时不妨换只耳朵、换双眼睛——少不是穷，是知道什么该留。',
