        description: '对韵段，原文：「清对浊，美对嘉。鄙吝对矜夸。花须对柳眼，屋角对檐牙。」此为《笠翁对韵·六麻》第一段开篇，也是六麻韵的第一课，前接 753 课五歌收尾。清对浊是反义成对：水清见底、水浊无光，《楚辞·渔父》「沧浪之水清兮，可以濯吾缨；沧浪之水浊兮，可以濯吾足」，同一条水清时洗帽缨浊时洗脚；清浊既是水也是世道，清则出仕、浊则退隐，古人论人亦分清流浊流。美对嘉是近义成对：《说文》「嘉，美也」，嘉肴嘉礼嘉宾皆指好，字形从壴（鼓）从加，本指乐声和美；近义词并排不为重复而为换字，一个字连用两遍就旧了，且美为上声、嘉为平声，一沉一扬，此对靠声音不靠意思。鄙吝对矜夸是两个毛病：鄙是边远粗陋引申为见识浅，吝是舍不得，合为胸襟窄，《后汉书·黄宪传》时人语「时月之间不见黄生，则鄙吝之萌复存乎心」，黄叔度器量汪洋能化人之吝；矜读 jīn，自恃自夸，《尚书·大禹谟》「汝惟不矜，天下莫与汝争能」，不夸反倒无人争得过；一往里收一往外放，专挑坏字成对且对得端正。花须对柳眼：花须即花蕊，细长丛生如须；柳眼是初生柳芽，细长微弯如刚睁之眼；李商隐《二月二日》「花须柳眼各无赖，紫蝶黄蜂俱有情」，此联所本。屋角对檐牙：屋角是房屋转角，檐牙是屋檐翘起之尖，排列如齿；杜牧《阿房宫赋》「廊腰缦回，檐牙高啄」，檐角如鸟嘴上啄。对法：清对浊反义，美对嘉近义，反义见分别、近义见分量；鄙吝对矜夸同类之病一窄一浮；花须柳眼屋角檐牙四词皆借人身部位喻外物——须眼角牙本是身上说法，移说草木屋宇，死物便活，云脚山腰雨丝风口同此一法。韵：嘉 jiā、夸 kuā、牙 yá 三个韵脚同属下平六麻，此课为六麻第一课。落点：清浊是水的事也是人的事；鄙吝是往里缩，矜夸是往外飘，一味缩的人不肯给，一味飘的人不肯听；看物要看得出人的样子，做人才不至于活成一件物。',
