        grade: '小学低中年级',
        description: '对韵段，原文：「志和宅，博望槎。秋实对春华。乾炉烹白雪，坤鼎炼丹砂。」此为《笠翁对韵·六麻》第一段第二课，前接 754 课六麻开篇。志和宅：张志和号玄真子、又自号烟波钓徒，一首《渔歌子》「西塞山前白鹭飞，桃花流水鳜鱼肥」传世；《新唐书》记颜真卿守湖州，见其舟敝欲为更之，张志和答「愿为浮家泛宅，往来苕霅间」——他的宅不是房子，是那条旧船，人住水上，家在船中。博望槎：张骞封博望侯，槎读 chá，是把木头捆起下水漂的木筏；《博物志》记旧说天河与海相通，年年八月有浮槎去来不失期，有人赍粮乘槎而去，至一处见城郭、织妇与牵牛人，问此何处，答「还问严君平」，归而问术士严遵，严遵谓某年月日有客星犯牵牛宿，正是此人到天河之时；正史张骞凿空西域走的是沙漠，后世把这桩奇事附会在他身上，杜甫「奉使虚随八月槎」、李商隐「海客乘槎上紫氛」皆用此典。二人都姓张，一陆一水、一隐一使、一辞官一奉使，正成一对。秋实对春华：华即花，古时一字，读 huá；春开花、秋结果，《颜氏家训·勉学》「讲论文章，春华也；修身利行，秋实也」——说得漂亮是花，做得实在才是果，此对不只写时序，还说质与文、内与外。乾炉烹白雪，坤鼎炼丹砂：乾读 qián，为八卦首卦、为天为阳；坤为第二卦、为地为阴；炉生火在上、鼎盛料在下，天为炉、地为鼎；丹道有「黄芽白雪」之说，白雪是水银别名，色白如雪，丹砂即朱砂，色赤，二者正是烧炼的原料，烹是煮、炼是熬，两个动火的字各占一法；一句里乾对坤、炉对鼎、烹对炼、白对丹、雪对砂，五处咬得死，不是写景，是把天地当丹房。对法：宅对槎一静一动、一陆一水；实对华一时序一本来；乾对坤一天一地，白对丹是色、雪对砂是物。韵：槎 chá、华 huá、砂 shā 三个韵脚同属下平六麻，与 754 课的嘉、夸、牙同段。落点：安身不必有房，一叶舟也是家；行路不妨往天上去，木筏也能到银河；花开时看花、果熟时吃果，别把花当成果；天地是一口大炉，人这一生就是慢慢把自己炼出来。',
