        num: '756',
        id: '756-shen-xiao-wang-leng',
        title: '对韵 · 沙场月冷，僧道一墙',
        subtitle: '六麻对课',
        path: 'lessons/756-shen-xiao-wang-leng/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「深宵望冷沙场月，边塞听残野戍笳。满院松风，钟声隐隐为僧舍；半窗花月，锡影依依是道家。」此为《笠翁对韵·六麻》第一段收尾第三课，前接 755 课，六麻第一段到此收齐。深宵望冷沙场月：深宵即深夜，沙场即战场，王翰「醉卧沙场君莫笑，古来征战几人回」、王昌龄「秦时明月汉时关」皆同此境；望冷是望着那冷月、望得心也冷，月本无温，「冷」是看月的人给的，古诗词里冷月寒月霜月，写的都是人不是天。边塞听残野戍笳：边塞为边疆关塞，野戍为荒野中的驻防营垒，戍读 shù，「野」字说明此处连城墙都没有；笳读 jiā，即胡笳，汉时流行于塞北西域的管乐器，声悲，蔡文姬作《胡笳十八拍》，李益「不知何处吹芦管，一夜征人尽望乡」同是此声；听残是笳声将尽未尽，最揪心，「冷」说心、「残」说天，一个感觉一个时候。两句七字逐字对位：深对边、宵对塞、望对听、冷对残、沙对野、场对戍、月对笳，一远一近、一眼一耳，七处全对一处不松。满院松风，钟声隐隐为僧舍：松风即松涛，风过松林其声如涛，「满」字把整个院子填满，声音是有体积的；钟声隔树传来故曰隐隐，「为」在此当「是」讲，读 wéi——听钟便知是和尚住的地方。半窗花月，锡影依依是道家：月照花枝，花影落窗只占半扇，「半」不是残缺而是留白，全占便俗；锡是锡杖，杖头有环，摇动作声，本是比丘十八物之一，僧家用来提醒脚下虫蚁、乞食叩门，道士亦持杖修行，故借「锡影」指持杖之人的身影；依依是依稀、仿佛，看不清面目只认得出装束。对法：满院对半窗，一满一半；院对窗，一大一小；松风对花月，一声一色；钟声对锡影，一听一看；隐隐对依依，两个叠词都写不分明；僧舍对道家，一释一道。前两句写边关之苦，后两句写山门之闲，中间隔着一轮月。韵：笳 jiā、家 jiā 两个韵脚同属下平六麻，与 754 课的嘉夸牙、755 课的槎华砂同段。落点：同一轮月亮，照沙场也照僧舍道观；听笳的人睡不着，听钟的人心就静了——地方由不得自己选，心境可以自己安；满的不必骄，半的也不必憾，认得清就够了，不必样样看清。',
