        num: '757',
        id: '757-lei-dui-dian',
        title: '对韵 · 雷动霞飞，一听一看',
        subtitle: '六麻对课',
        path: 'lessons/757-lei-dui-dian/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「雷对电，雾对霞。蚁阵对蜂衙。寄梅对怀橘，酿酒对烹茶。」此为《笠翁对韵·六麻》第二段开篇第一课，前接 756 课六麻第一段收尾。雷对电：雷是声、电是光，先见闪电后闻雷，只因光比声快，古人分成两个名字，眼睛和耳朵各记了一次账；《易·说卦》「动万物者莫疾乎雷」，雷一动万物皆醒。雾对霞：雾是贴地的水汽，白茫茫把东西藏起来；霞是日光染过的赤云，《说文》「霞，赤云气也」，王勃「落霞与孤鹜齐飞」；同一口水汽，落在低处是雾，升到高处染了光是霞。蚁阵对蜂衙：蚂蚁搬家行军一只跟一只行列不乱，古人称「蚁阵」，是虫子的兵阵，《南柯太守传》淳于棼梦入槐安国做太守，醒后方知是槐树下的蚁穴；蜜蜂早晚各聚一次，进进出出如旧时属吏排班参见长官，故称「蜂衙」，陆游「微雨晴时看鹤舞，小窗幽处听蜂衙」；阵是兵的编制、衙是官的编制，都是把虫子看成有规矩的人。寄梅对怀橘：南朝宋陆凯与范晔相善，自江南折梅一枝托驿使送到长安，附诗「江南无所有，聊赠一枝春」——没有别的东西，只有这一点春天；《三国志·陆绩传》陆绩六岁于九江见袁术，术出橘，绩怀三枚，辞时堕地，袁术问「陆郎作宾客而怀橘乎」，绩跪答「欲归遗母」，遗读 wèi 是赠送；寄是往外寄、怀是往怀里藏，一远一近，友情对孝心。酿酒对烹茶：酒靠粮食发酵，蒸熟下曲封缸，日子不到不开坛，《世本》有仪狄始作酒醪、少康作秫酒之说；烹即煮，唐人煮茶看水泡认火候，小泡叫蟹眼、大些叫鱼眼，苏轼「蟹眼已过鱼眼生，飕飕欲作松风鸣」，陆羽《茶经》「茶者，南方之嘉木也」，水一老茶就苦；酿要等、烹要急，酒烈茶清，都是待客之物。对法：雷对电一听一看，雾对霞一低一高，蚁阵对蜂衙一兵一官，寄梅对怀橘一远一近，酿酒对烹茶一慢一快。韵：霞 xiá、衙 yá、茶 chá 三个韵脚同属下平六麻，与 754 课的嘉夸牙、755 课的槎华砂、756 课的笳家同段；雷、电、雾不在句尾，不押韵。落点：天上没有两件事，只有一张脸的两面；情不在贵重，在想着谁；有的事等得起，有的事等不得。',
