        title: '对韵 · 梦飞天涯，两地相思',
        subtitle: '六麻对课',
        path: 'lessons/759-wu-xie-ge-lou/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「舞榭歌楼千万尺，竹篱茅舍两三家。珊枕半床，月明时梦飞塞外；银筝一奏，花落处人在天涯。」此为《笠翁对韵·六麻》第二段收尾，前接 758 课。舞榭歌楼千万尺：榭读 xiè，是建在高台上四面敞开的屋子，不砌墙只立柱，供歌舞宴饮；舞榭歌楼四字连读便是一片笙歌不停之地，是一种日子而非一栋楼；千万尺不是实指而是夸张，把气派堆到天上，李白「飞流直下三千尺」、杜甫「霜皮溜雨四十围」皆以数字量心情，此处只为垫出一个「高」字。竹篱茅舍两三家：竹篱为竹编矮墙，茅舍为茅草盖屋，都不用一块砖；两三家言人烟稀少，鸡犬相闻而不相扰；辛弃疾「茅檐低小，溪上青青草」写其心安，陶渊明「草屋八九间」、杜甫草堂皆是自盖。对法：舞榭对竹篱一华一朴，歌楼对茅舍一闹一静，千万尺对两三家一多一少、一高一低，数字对数字，一字不用评而高下冷暖自见。珊枕半床，月明时梦飞塞外：珊枕是珊瑚装饰或镶嵌的枕头，泛指讲究枕具，枕愈讲究愈显人孤单；半床是一张床只睡半边，空的那半边就是缺席的人，古人写孤单常从空出来的地方下手；月明时睡不着，睡着便做梦，梦里一脚跨出几千里，金昌绪《春怨》「啼时惊妾梦，不得到辽西」正怕梦断；李白「长安一片月，万户捣衣声」、王昌龄「可怜闺里月，长在汉家营」，同一轮月照家里也照边关，故梦往那边飞。银筝一奏，花落处人在天涯：筝为弦乐器，银筝言其华美，一奏是才起手，曲子与心事都未终；一个人弹给自己听，多半是没人可说话；花落处是眼前，人在天涯是远处，景近而人远；马致远「夕阳西下，断肠人在天涯」、晏殊「无可奈何花落去」皆此意。对法：珊枕对银筝一枕一筝皆一人之物，半床对一奏一空一响，梦飞塞外对人在天涯一虚一实、一梦一醒。韵：家 jiā、涯 yá 两个韵脚同属下平六麻，与 757 课的霞衙茶、758 课的花葭笳同段；「尺」在句尾却不押韵，只作对字。落点：富贵与清贫都是日子，楼再高睡下只要半张床，屋再矮月亮照样照进来；最难受的不是穷，是人不在身边——梦比路近，琴比话长。此课收六麻第二段，下一课起为第三段「圆对缺，正对斜」。',
