        description: '对韵段，原文：「百舌鸟，两头蛇。帝里对仙家。尧仁敷率土，舜德被流沙。」此为《笠翁对韵·六麻》第三段后半，前接 759 课。百舌鸟即乌鸫，又名反舌，能反复其舌、随百鸟之音，故称百舌；《礼记·月令》「小暑至，反舌无声」，春啭夏止；杜甫《百舌》「知音兼众语，整翮岂多身」，末句「过时如发口，君侧有谗人」，借鸟讽人，说巧言多变者如君王身边的谗臣。两头蛇：古人以为见者必死，楚地尤信；世上真有一头两尾的蛇，所谓两头蛇多是把缠在一处的蛇看错。刘向《新序·杂事一》载孙叔敖为婴儿时出游，见两头蛇，杀而埋之，归而泣，母问其故，对曰「闻见两头之蛇者死，向者吾见之，恐去母而死也」；母问蛇今安在，曰「恐他人又见，杀而埋之矣」；母曰「吾闻有阴德者，天报以福，汝不死也」；及长为楚令尹，未治而国人信其仁。帝里即京城，天子所在，骆宾王《帝京篇》「山河千里国，城阙九重门」；仙家为仙人所居，云山洞天，李白「桃花流水窅然去，别有天地非人间」。对法：帝里对仙家，一挤一空、一争一让、一朝一山。尧仁敷率土：敷是布开，率土出《诗经·小雅·北山》「率土之滨，莫非王臣」，指四海之内。舜德被流沙：被是覆盖、及于，流沙指西北大漠，《尚书·禹贡》「东渐于海，西被于流沙」，舜的德行远及人走不到的地方。韵：蛇 shé、家 jiā、沙 shā 同属下平六麻；鸟、土在句尾而不入韵，只作对字。落点：嘴巧不如心正，说得好听不算本事，做得实在才算；真正的大，是德行铺到别人看不见的地方。此课收六麻第三段后半，下一课起为「桥上授书曾纳履，壁间题句已笼纱」。',
