        grade: '小学低中年级',
        description: '对韵段，原文：「桥上授书曾纳履，壁间题句已笼纱。远塞迢迢，露碛风沙何可极；长沙渺渺，雪涛烟浪信无涯。」此为《笠翁对韵·六麻》第三段收尾，六麻全韵到此讲完，前接 760 课。桥上授书曾纳履：《史记·留侯世家》载张良在下邳圯上遇老父，老父直堕其履圯下，命良下取履，又曰「履我」，良长跪履之；老父三约（平明、鸡鸣、夜未半）以试其忍，后出一编书曰「读此则为王者师矣」，旦日视之乃《太公兵法》；纳履即穿鞋，《乐府诗集·君子行》「瓜田不纳履，李下不正冠」。苏轼《留侯论》「天下有大勇者，卒然临之而不惊，无故加之而不怒」，正为此事而发。壁间题句已笼纱：唐王播少孤贫，客扬州惠昭寺木兰院，随僧斋餐，僧厌之，饭后击钟，播至而饭已罄；后二纪出镇是邦，访旧游，见昔所题诗已以碧纱幕其上，因题「上堂已了各西东，惭愧阇黎饭后钟。二十年来尘扑面，而今始得碧纱笼」。笼读 lǒng，罩住。远塞迢迢，露碛风沙何可极：塞为边关，迢迢是路远；碛读 qì，不生草木的沙石地，露碛即裸露无遮的荒漠；极是尽头。王维「大漠孤烟直，长河落日圆」写此空阔。长沙渺渺，雪涛烟浪信无涯：渺渺为水势辽远，雪涛是白浪如雪，烟浪是水气如烟，信是确实，涯是边；「长沙」一作「长江」，两版意思相通，皆言水远无岸。对法：桥上对壁间、授书对题句、曾对已、纳履对笼纱，一低一高、一求一报；远塞对长沙，一旱一水；露碛风沙对雪涛烟浪，四名两两；何可极发问，信无涯作答。韵：纱 shā、涯 yá、沙 shā 同属下平六麻，履 lǚ 在句尾而不入韵，只作对字。落点：人一生有低头的时候，也有被高看的时候；低头是为了走远，不是认输，被高看是别人的势利，不是自己的本事。此课收六麻第三段，下一课起为第四段「疏对密，朴对华」。',
