        grade: '小学低中年级',
        description: '对韵段，原文：「疏对密，朴对华。义鹘对慈鸦。鹤群对雁阵，白苎对黄麻。」此为《笠翁对韵·六麻》第四段开头，前接 761 课。疏对密：疏是稀、空，密是稠、满，书画论有「疏处可以走马，密处不使透风」（包世臣《艺舟双楫》记邓石如论书语）。朴对华：朴是本色，华是文饰；《老子》「见素抱朴」，孔子「质胜文则野，文胜质则史，文质彬彬，然后君子」（《论语·雍也》）。义鹘对慈鸦：鹘读 hú，鹰类猛禽，杜甫《义鹘行》载白蛇吞苍鹰雏子，苍鹰向鹘诉苦，鹘冲下九天爪裂蛇首为鹰报仇，事毕即去，故称义鹘；慈鸦即乌鸦，老鸦不能取食时小鸦反哺其母，古人称孝乌、慈鸦，白居易有《慈乌夜啼》。鹤群对雁阵：鹤为仙禽，《诗经·小雅·鹤鸣》「鹤鸣于九皋，声闻于天」，群鹤散飞各各自在；雁南飞排成「一」字或「人」字，行列整齐，称雁阵，古人又以雁序比兄弟长幼。白苎对黄麻：苎读 zhù，麻类，皮可织布，白苎即白麻布，百姓所服，晋有《白苎歌》舞曲；黄麻亦麻类，所作纸色黄，唐宋以黄麻纸写诏书，故「黄麻」代指诏命。对法：疏对密是空与满，朴对华是素与艳，一放一收；义对慈，刚对柔，一个管外一个管内；群对陈，散对整；白对黄是颜色，苎对麻同出一草，一在野一在朝。韵：华 huá、鸦 yā、麻 má 同属下平六麻，密、阵在句尾而不入韵，只作对字。落点：不是越满越好，也不是越素越好，配得合适才算好；本色是根，修饰是叶，根不丢，叶才好看。此课起六麻第四段，下一课为「读三到，吟八叉」。',
