        grade: '小学低中年级',
        description: '对韵段，原文：「读三到，吟八叉。肃静对喧哗。围棋兼把钓，沉李并浮瓜。」此为《笠翁对韵·六麻》第四段第二段，前接 762 课。读三到：朱熹《训学斋规》「余尝谓读书有三到，谓心到、眼到、口到……三到之中，心到最急」，口到是出声朗读，眼到是字字看清，心到是想着意思。吟八叉：晚唐温庭筠才思敏捷，每入试押官韵作赋，「八叉手而八韵成」，时号「温八叉」；叉手是两手交叉拱于胸前，八叉手只是八次拱手的时间，极言其快。肃静对喧哗：肃静是肃穆安静，喧哗是声音杂乱，一静一闹，反义成对。围棋兼把钓：围棋相传为尧所造以教丹朱，《博物志》「尧造围棋，丹朱善之」；晋王质入山观童子下棋，棋未终而斧柯已烂，归家已历数世，是为烂柯；把钓是手持钓竿，姜尚渭水、严光富春、张志和自称烟波钓徒，皆此一路。兼是两样兼有，一动脑一静心。沉李并浮瓜：曹丕《与朝歌令吴质书》「浮甘瓜于清泉，沉朱李于寒水」，夏日以清泉寒水冰镇果品，后成「浮瓜沉李」一语。对法：读对吟同为口事，三对八是数字，到对叉是动作落处；肃静对喧哗反义相形；围棋对把钓同为坐着的闲事；沉对浮反义，李对瓜同类。韵：叉 chā、哗 huá、瓜 guā 同属下平六麻，到、钓在句尾而不入韵，只作对字。落点：读书三到，最急的是心到；八叉成韵看着快，底子是读得多、记得熟；人要有静下来读书的时候，也要有下棋钓鱼、浮瓜沉李的闲工夫。此课起六麻第四段第二段，下一课为「羽客片时能煮石，狐禅千劫似蒸沙」。',
