        path: 'lessons/764-zhu-shi-zheng-sha/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「羽客片时能煮石，狐禅千劫似蒸沙。党尉粗豪，金帐笼香斟美酒；陶生清逸，银铛融雪啜团茶。」此为《笠翁对韵·六麻》第四段收尾，六麻全韵到此讲完，前接 763 课。羽客片时能煮石：羽客即道士，道家尚羽衣飞升，故称；晋葛洪《神仙传》记白石先生常煮白石为粮，就白石山居，号白石先生；道家言丹术能点化金石，片时成事，故曰片时。狐禅千劫似蒸沙：禅宗讥似是而非、未真开悟者为野狐禅，《五灯会元》载百丈怀海说法，一老人自云昔住此山，因答「大修行人还落因果无」曰「不落因果」，遂堕野狐身五百生；百丈令代一转语，答曰「不昧因果」，老人言下大悟，脱野狐身。千劫是极长之时；蒸沙出《楞严经》「如蒸沙石，欲其成饭，经百千劫，秖名热沙」，沙非饭本，煮久亦不成饭。党尉粗豪，金帐笼香斟美酒：党尉谓宋初大将党进，行伍出身，性粗豪；金帐即销金帐，《事文类聚》载宋陶谷得党太尉家姬，雪天烹茶，问「党家有此味否」，姬曰「彼但知坐销金帐里，共饮羊羔美酒，浅斟低唱而已」。陶生清逸，银铛融雪啜团茶：陶生谓陶谷，宋初翰林学士，性喜清雅，旧有陶学士扫雪烹茶之说；铛读 chēng，一种温器小锅，银铛即银制者；团茶为宋代压成饼的贡茶，饮时碾碎煎煮，啜是小口饮。对法：羽客对狐禅，一真一伪；片时对千劫，极短对极长；能煮石对似蒸沙，一成一败；党尉对陶生，一武一文；粗豪对清逸，一热一冷；金对银、帐对铛、美酒对团茶，器物与滋味皆成对。韵：沙 shā、茶 chá 同属下平六麻，石 shí、酒 jiǔ 在句尾而不入韵，只作对字。落点：成事不在熬多久，在路子对不对——路子错了，千劫蒸沙终是热沙；日子也不止一种过法，金帐美酒是热闹，银铛雪茶是清味，能安下这杯清茶，才算真会过。此课收六麻第四段，六麻全韵至此讲完，下一课起为下卷七阳第一段「台对阁，沼对塘」。',
