        description: '对韵段，原文：「三寸舌，九回肠。玉液对琼浆。秦皇照胆镜，徐肇返魂香。」此为《笠翁对韵·七阳》第一段第二段，前接 765 课。三寸舌：指口才，《史记·平原君虞卿列传》毛遂说楚，「以三寸之舌，强于百万之师」；《留侯世家》张良亦称「以三寸舌为帝者师」。九回肠：言愁思郁结，司马迁《报任安书》「肠一日而九回」，柳宗元「江流曲似九回肠」，九是极言其多。玉液对琼浆：玉液、琼浆皆为美酒之美称，道家亦以为仙家服食之物，故与「液」「浆」相配。秦皇照胆镜：《西京杂记》卷三载咸阳宫中方镜，广四尺、高五尺九寸，表里有明，人扪心而照则见肠胃五脏，女子有邪心则胆张心动；秦始皇常以照宫人，胆张心动者杀之。徐肇返魂香：明《香乘》引宋洪刍《香谱》，司天主簿徐肇遇苏氏子德哥，善为返魂香，撮香入炉，烟袅直上，微吟「东海徐肇，欲见先灵，愿此香烟，用为引道」，遂见父母曾高；德哥曰「但死经八十年以上者，则不可返矣」。返魂香之名早见旧题东方朔《海内十洲记》，聚窟洲有返魂树，死者闻香乃活。对法：三对九是数字，寸对回是量，舌对肠是身，一出于口、一结于中；玉液对琼浆同义相俪；秦皇对徐肇是人名，照胆对返魂是动宾，镜对香是器物——一帝一吏，一照心一返魂。韵：肠 cháng、浆 jiāng、香 xiāng 同属下平七阳，舌 shé、镜 jìng 在句尾而不入韵，只作对字。落点：舌小话重，一句话能顶百万兵，也能伤人，说前先想一想；愁思缠成九回肠，苦的是自己；照胆镜照得见心，返魂香却唤不回已去的人——趁人在，多陪伴。此课续七阳第一段，下一课为「青萍夜啸芙蓉匣，黄卷时摊薜荔床」。',
