        grade: '小学低中年级',
        description: '对韵段，原文：「青萍夜啸芙蓉匣，黄卷时摊薜荔床。元亨利贞，天地一机成化育；仁义礼智，圣贤千古立纲常。」此为《笠翁对韵·七阳》第一段收尾，前接 766 课。青萍：古剑名，《抱朴子》以「青萍、豪曹」并举，皆天下利器；后世遂以青萍代宝剑。夜啸：宝剑有灵，在匣中夜作鸣声，旧说剑鸣主不平，龙泉、太阿化龙事可参。芙蓉匣：刻莲花纹的剑匣，芙蓉即荷花，李白「雪花照芙蓉」亦以芙蓉状剑光。黄卷：古书以黄檗染纸防蠹，纸色发黄，故称书为黄卷，「黄卷青灯」即读书人清苦生涯。时摊：不时摊开诵读，陶渊明「时还读我书」近之。薜荔床：薜荔为蔓生香草，《楚辞·九歌·山鬼》「被薜荔兮带女萝」；以薜荔为床，写幽人隐居清贫之状。对法：青萍对黄卷是剑对书、武对文；夜对时是时辰；啸对摊是一有声一无声、一动一静；芙蓉匣对薜荔床是花名加器物，字面极工。元亨利贞：《周易·乾》卦辞四字，《文言》释为「元者善之长也，亨者嘉之会也，利者义之和也，贞者事之干也」；汉儒以之配仁义礼智，元配仁、亨配礼、利配义、贞配智。天地一机成化育：一机即一点生机，《易》「天地之大德曰生」；化育谓化生养育，《中庸》「万物育焉」。仁义礼智：孟子四端，恻隐之心仁之端、羞恶之心义之端、辞让之心礼之端、是非之心智之端。纲常：三纲五常之省称，五常即仁义礼智信；圣贤立之，为千古做人准绳。韵：床 chuáng、常 cháng 同属下平七阳，匣 xiá、育 yù 在句尾而不入韵，只作对字。落点：剑在匣中要鸣，是血性未冷；书在床头常摊，是心气不浊——一个人既要有锋芒，也要有书卷。天地以生机养万物之身，圣贤以纲常立人心之正；三纲是旧时代的产物，仁义礼智四字却仍站得住。此课收七阳第一段，下一课起七阳第二段「红对白，绿对黄」。',
