        path: 'lessons/768-hong-dui-bai/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「红对白，绿对黄。昼永对更长。龙飞对凤舞，锦缆对牙樯。」此为《笠翁对韵·七阳》第二段开头，前接 767 课。红对白，绿对黄：四色两两成对，取反差而非相同；古人分正色与间色，青赤黄白黑为正色，绿为青黄之间的间色，正色做礼服、间色做便服；诗中颜色成对者如杜甫「两个黄鹂鸣翠柳，一行白鹭上青天」、蒋捷「红了樱桃，绿了芭蕉」。昼永对更长：昼是白天，永是长，夏至前后昼最长；更读 gēng，是夜里的更次，一夜五更，冬至前后夜最长。昼对更是以时段相对，永对长是同义相俪，字字皆工。龙飞对凤舞：龙飞出《易·乾》九五「飞龙在天，利见大人」，为帝王之象，九五之尊本此；凤舞本《尚书·益稷》「箫韶九成，凤凰来仪」，乐成而凤至。后世以「龙飞凤舞」状气势奔放，尤以评书法笔势为多。锦缆对牙樯：锦缆是锦制的缆绳，牙樯是象牙饰的桅杆，出杜甫《秋兴八首》其六「珠帘绣柱围黄鹄，锦缆牙樯起白鸥」，写曲江游船之盛；亦令人想隋炀帝龙舟下江都，锦帆千里。对法：红白绿黄是颜色自对，昼永更长是时段相对，龙飞凤舞是灵物加动作，锦缆牙樯是材质加器物，一虚一实，两两相生。韵：黄 huáng、长 cháng、樯 qiáng 同属下平七阳，舞 wǔ 在句尾而不入韵，只作对字。落点：颜色要对得准，日子要看得清——昼长夜长都是天时，不必争；龙飞凤舞是气象，锦缆牙樯是排场，热闹看得，别只盯排场，船能走靠樯结实，不靠樯镶牙。此课起七阳第二段，下一课为「云弁使，雪衣娘」。',
