        grade: '小学低中年级',
        description: '对韵段，原文：「云弁使，雪衣娘。故国对他乡。雄文能徙鳄，艳曲为求凰。」此为《笠翁对韵·七阳》第二段第二段，前接 768 课。云弁使：指蜻蜓。崔豹《古今注》说蜻蜓「一名赤衣使者，好集水上，亦名赤弁丈人」；蜻蜓头形如古人所戴之弁（礼冠），故称。李渔为与「雪」相对，把「赤」改作「云」，遂成「云弁使」。雪衣娘：白鹦鹉，唐郑处诲《明皇杂录》载开元中岭南献白鹦鹉，聪慧洞晓言词，玄宗与贵妃呼为雪衣女，宫人呼为雪衣娘；后为鸷鸟所搏，葬于苑中，称鹦鹉冢。故国对他乡：故国是老家旧国，他乡是客居之地，一亲一生，反义成对；杜甫「月是故乡明」、王维「独在异乡为异客」、李煜「故国不堪回首月明中」皆此意。雄文能徙鳄：韩愈谏迎佛骨贬潮州刺史，恶溪有鳄食民畜，愈作《祭鳄鱼文》投溪而祝，限三日、五日、七日南徙于海；《新唐书》载祝之夕暴风震电起溪中，数日水尽涸，西徙六十里。艳曲为求凰：司马相如于卓王孙宴上弹琴歌《凤求凰》「凤兮凤兮归故乡，遨游四海求其凰」，卓文君夜奔相如。对法：云对雪是天上之物，弁对衣是身上之物，使对娘是身份之称，一虫一鸟，极工；故国对他乡是反义；雄文对艳曲是庄对艳，能徙鳄对为求凰是动宾相对，一驱害一求偶。韵：娘 niáng、乡 xiāng、凰 huáng 同属下平七阳，鳄 è 在句尾而不入韵，只作对字。落点：小物也有名号，蜻蜓叫「使者」，鹦鹉叫「娘子」，起名见性情；文章能驱鳄是古人的信念——话说到理上，就有力量；求凰是少年心事，不必笑它艳。此课续七阳第二段，下一课为「九日高峰惊落帽，暮春曲水喜流觞」。',
