        grade: '小学低中年级',
        description: '对韵段，原文：「九日高峰惊落帽，暮春曲水喜流觞。僧占名山，云绕茂林藏古殿；客栖胜地，风飘落叶响空廊。」此为《笠翁对韵·七阳》第二段收尾，前接 769 课。九日高峰惊落帽：用孟嘉落帽事。《晋书·孟嘉传》载桓温九月九日宴于龙山，僚佐毕集，风吹孟嘉帽落，嘉不之觉；温命孙盛作文嘲之，嘉即答之，其文甚美，四坐嗟叹。后世「落帽」遂为重阳登高宴集之典，杜甫「羞将短发还吹帽，笑倩旁人为正冠」即用此。暮春曲水喜流觞：用兰亭修禊事。永和九年三月三日上巳，王羲之与谢安、孙绰等会于会稽山阴之兰亭，引以为流觞曲水，列坐其次，觞至则饮、饮则赋诗，羲之作《兰亭集序》；觞读 shāng，是酒杯。僧占名山，云绕茂林藏古殿：语本《增广贤文》「天下名山僧占多」，李渔曾作联为道家鸣不平「也该留一二奇峰，栖吾道友」；云绕茂林、藏住古殿，是山中寺院的实景，也是中国画「藏」的趣味。客栖胜地，风飘落叶响空廊：客是游子，栖是寄居（本义鸟停树上，取暂时之意）；胜地是风景佳处。落叶响空廊写静——廊愈空，叶声愈响；亦令人联想吴王响屧廊，西施着木屐行于空廊，声声皆音。对法：九日对暮春是时节，一秋一春；高峰对曲水是地，一高一低；惊对喜是情，一惊一喜；落帽对流觞是事，一落一举；僧占对客栖是人与动作，名山对胜地，云绕对风飘，茂林对落叶，藏古殿对响空廊，一藏一响，字字成双。韵：觞 shāng、廊 láng 同属下平七阳，帽 mào 在句尾而不入韵，只作对字。落点：落帽不觉是气度，流觞赋诗是风流——都是心不急；名山被僧占去，是佛法盛，也是人间求个清静处所；风一吹，叶一响，空廊才知道自己空。此课收七阳第二段，下一课起七阳第三段「衰对壮，弱对强」。',
