        grade: '小学低中年级',
        description: '对韵段，原文：「衰对壮，弱对强。艳饰对新妆。御龙对司马，破竹对穿杨。」此为《笠翁对韵·七阳》第三段开头，前接 770 课。衰对壮，弱对强：反义相对。衰读 shuāi，是气血往下走；壮是筋骨正盛。《论语·季氏》「及其老也，血气既衰，戒之在得」。弱是力不如人，强是压得住人；《老子》「柔弱胜刚强」，水最柔而能穿石。艳饰对新妆：此处换同义相对。艳本义是丰美、色浓，饰是头上身上的装点；新妆是刚梳好的头面，刘禹锡「新妆宜面下朱楼」，《木兰诗》「当窗理云鬓，对镜贴花黄」。御龙对司马：《左传·昭公二十九年》蔡墨述古官，有豢龙氏、御龙氏；刘累学扰龙于豢龙氏，以事孔甲，能饮食之，孔甲赐氏曰御龙。司马是官名，《周礼》夏官大司马掌邦政，后世为三公之一，姓亦由此出，司马迁、司马相如即其后。破竹对穿杨：破竹出《晋书·杜预传》，伐吴之议，预曰「今兵威已振，譬如破竹，数节之后，皆迎刃而解，无复著手处也」；穿杨出《战国策·西周策》，「楚有养由基者，善射，去柳叶者百步而射之，百发百中」，杨即柳。对法：衰对壮、弱对强是反义，艳对新、饰对妆是同义，一副对子里两种对法并用；御对司是掌管之动词，龙对马是能驾之名物，御龙氏与司马又同为官称；破对穿是动作，竹对杨是草木，一势一巧。韵：强 qiáng、妆 zhuāng、杨 yáng 同属下平七阳；壮 zhuàng 在去声、马 mǎ 在上声，居句尾而不入韵，只作对字。落点：盛衰由天，强弱由己——年岁改不了，练一样本事，弱就变强；破竹先攒势，穿杨先练准，做事两样都要。此课起七阳第三段，下一课为「读班马，识求羊。水色对山光」。',
