        grade: '小学低中年级',
        description: '对韵段，原文：「读班马，识求羊。水色对山光。仙棋藏绿橘，客枕梦黄粱。」此为《笠翁对韵·七阳》第三段第二段，前接 771 课。读班马：班是班固，作《汉书》；马是司马迁，作《史记》，两人并称「班马」，《晋书》已有「班马迭兴」之语；读是读其书。识求羊：求是求仲，羊是羊仲，汉蒋诩归隐杜陵，舍前竹下开三径，惟故人求仲、羊仲从之游，二人皆隐士，见《三辅决录》；识是识其人。水色对山光：水色随天变，晴碧雨灰；山光随日变，朝翠暮紫。苏轼「水光潋滟晴方好，山色空蒙雨亦奇」，一句里两样都有。仙棋藏绿橘：《玄怪录》记巴邛人橘园霜后余二大橘，剖开各有一对老叟对坐下棋，身长尺余，一叟曰「橘中之乐，不减商山，但不得深根固蒂，为愚人摘下耳」；后「橘中戏」遂为象棋雅称。客枕梦黄粱：沈既济《枕中记》卢生困于邯郸道，道士吕翁授以青瓷枕，梦中娶妻登第、位至宰相，历五十年，八十而卒；欠伸而寤，身仍在邸舍，主人蒸黍未熟。对法：读对识是动词，班马对求羊是两人合称对两人合称；水对山是地，色对光是所见；仙对客一仙一凡，棋对枕一物一物，藏对梦一实一虚，绿对黄是颜色，橘对粱是果实对谷物。韵：羊 yáng、光 guāng、粱 liáng 同属下平七阳，一韵到底；马 mǎ 在上声，居句尾而不入韵，只作对字。落点：书里有前人的脚印，朋友里有活人的性情；一局棋、一场梦，乐与空都在方寸之间。此课承七阳第三段，下一课为「池草入诗因有梦，海棠带恨为无香」。',
