        grade: '小学低中年级',
        description: '对韵段，原文：「池草入诗因有梦，海棠带恨为无香。风起画堂，帘箔影翻青荇沼；月斜金井，辘轳声度碧梧墙。」此为《笠翁对韵·七阳》第三段末段，前接 772 课。池草入诗：南朝谢灵运任永嘉太守，病中登楼，梦见族弟谢惠连，忽得「池塘生春草，园柳变鸣禽」，自谓「此语有神功，非吾语也」，见《南史·谢惠连传》。海棠带恨：北宋惠洪《冷斋夜话》记刘渊材自言平生五恨，其四为「海棠无香」；恨是遗憾，不是仇恨。画堂＝宫中彩绘殿堂，泛指华丽堂舍；帘箔＝帘子，箔 bó 本指苇编的帘；青荇＝荇菜，《诗经·周南·关雎》「参差荇菜，左右流之」；沼＝水池。风吹画堂，帘影落在池上，像青荇翻动。金井＝井栏雕饰华美的井；辘轳 lù lú＝井上汲水的起重装置；度＝穿过；碧梧＝绿色梧桐，一作碧桐。月影斜照井栏，打水的辘轳声越过梧桐墙传来。对法：池草对海棠是草木对花木，入诗对带恨是动宾，因有梦对为无香是因果；风起对月斜是主谓，画堂对金井是建筑，帘箔影翻对辘轳声度是视觉对听觉，青荇沼对碧梧墙是植物对处所。韵：香 xiāng、墙 qiáng 属下平七阳；梦 mèng 去声、沼 zhǎo 上声，出句不入韵。落点：好句能从梦里来，憾事也能写进对子；一处小景既看得见影翻，也听得见声度，才算真的看见。此课为七阳第三段收尾，下一课为「臣对子，帝对王。日月对风霜」。',
