        grade: '小学低中年级',
        description: '对韵段，原文：「臣对子，帝对王。日月对风霜。乌台对紫府，雪牖对云房。」此为《笠翁对韵·七阳》其四开篇，前接 773 课。臣对子：君臣对父子，「君犹父也，臣犹子也」，臣是官吏，子是子女，讲名分各有其位。帝对王：周以前帝与王都指君主，秦始皇以后天子称帝、藩国称王，帝高于王。日月对风霜：日月是太阳月亮，引申时光；风霜是风和霜，引申艰辛；都是并列名词，日月仄仄、风霜平平。乌台：御史台，《汉书·朱博传》载御史府中列柏树，野乌数千栖宿其上，晨去暮来号「朝夕乌」，故称乌台、柏台；苏轼因诗被审即「乌台诗案」。紫府：道教仙人居所，《抱朴子》「及到天上，先过紫府，金床玉几，晃晃昱昱，真贵处也」，李商隐「紫府仙人号宝灯」；一在人间管法度，一在天上住仙人。雪牖：牖 yǒu 是窗户，徐坚《初学记》引《宋齐语》「孙康家贫，常映雪读书」。云房：僧道或隐士居所，姚合「天竺云房石磴危」，刘得仁「云房空见有仙经」。一苦读一隐居，一寒一清。通行本此段在「乌台对紫府」后尚有「蔀屋对岩廊。香山社，昼锦堂」，这里按所给次序先讲雪牖云房，原文不变。韵：王 wáng、霜 shuāng、房 fáng 属下平七阳；子 zǐ、帝 dì、府 fǔ 是仄声句尾不入韵。落点：先认清名分，再看懂时令，最后分得清人间的官署和天上的仙居——对子练的是把万事摆到各自的位置上。下一课为「香山社，昼锦堂。蔀屋对岩廊」。',
