        description: '对韵段，原文：「贫女幸分东壁影，幽心高卧北窗凉。绣阁探春，丽日半笼青镜色；水亭醉夏，薰风常透碧筒香。」此为《笠翁对韵·七阳》其四末段，前接 775 课。贫女幸分东壁影：齐国贫女徐吾家贫无烛，与邻女同室夜绩，她每天最早来扫地铺席，只求借东壁照过来的余光，说「一室之中多不为暗，少不为明，何惜东壁余光」，见《列女传》，李白「愿假东壁辉，余光照贫女」。这与匡衡凿壁偷光是两回事：匡衡是穿壁引光读书，这里是邻女分烛余光绩麻。幽心高卧北窗凉：陶潜《与子俨等疏》「五六月中，北窗下卧，遇凉风暂至，自谓是羲皇上人」；「幽心」古本一作「幽人」（隐士，多指陶渊明），课件按所给原文「幽心」讲，FAQ 说明异文。绣阁是女子闺房，探春是唐宋正月十五后士女郊游的风俗；青镜即青铜镜，笼读 lǒng，丽日半笼青镜色写春日闺中镜面映着阳光。水亭醉夏写水亭纳凉；薰风是夏天的东南风和风，舜《南风歌》「南风之薰兮，可以解吾民之愠兮」；碧筒是荷叶柄做的酒杯，三国魏郑悫三伏天以荷叶盛酒、刺通叶柄弯成象鼻吸饮，名「碧筒杯」，酒带荷叶清香。对法：贫女对幽心是人对心，幸分对高卧，东壁影对北窗凉是方位景物对；绣阁探春对水亭醉夏是处所加时令，丽日半笼对薰风常透，青镜色对碧筒香是器物对。韵：凉 liáng、香 xiāng 属下平七阳；影 yǐng 上声、色 sè 入声，出句不入韵。落点：借光不损人，纳凉不求人；穷有穷的志气，闲有闲的自在，四时各有各的好。下一课预告「形对貌，色对声」（下平八庚开篇）。',
