        description: '对韵段，原文：「形对貌，色对声。夏邑对周京。江云对涧树，玉磬对银筝。」此为《笠翁对韵·下平八庚》其一开篇段，前接 776 课，是新韵部八庚的第一课。形对貌：形体对容貌，都是人外在的样子；色对声：颜色凭眼睛看，声音凭耳朵听，一看一听正好成对。夏邑对周京：夏邑是夏朝的都城（禹都安邑，在今山西夏县一带），周京是周朝的都城（西周建都镐京，在今西安一带），朝代对朝代、都城对都城。江云对涧树：江上云对涧边树，大水对小水、天上对岸边，是写景的对子。玉磬对银筝：玉磬是玉石做的打击乐器，敲着响；银筝是弦乐器，弹着响，一敲一弹、一石一银，都是乐器。对法：形对貌是人体对外貌，色对声是一看一听；夏邑对周京是朝代都城对；江云对涧树是水对树、天对地；玉磬对银筝是乐器对乐器。韵：声 shēng、京 jīng、筝 zhēng 同属下平八庚；貌 mào 去声、树 shù 去声，出句不入韵。落点：开篇先从身边对起——样貌声音、城池山河、乐器金玉，都是孩子看得见、听得到的东西。下一课预告「人老老，我卿卿」（八庚其一后段）。',
