        description: '对韵段，原文：「贾客君山秋弄笛，仙人缑岭夜吹笙。帝业独兴，尽道汉高能用将；父书空读，谁言赵括善知兵。」此为《笠翁对韵·下平八庚》其一收尾段，前接 778 课。贾客君山秋弄笛：贾客即商人（贾读 gǔ），传说商人坐船过洞庭湖君山，秋夜遇仙人吹笛。仙人缑岭夜吹笙：周灵王太子晋（王子乔）好吹笙作凤凰鸣，传说后来七月七日乘白鹤现于缑氏山头（缑岭，缑读 gōu），拱手与世人道别；一江一山、一笛一笙。帝业独兴，尽道汉高能用将：汉高祖刘邦出身亭长而建汉朝，韩信说他「不能将兵，而善将将」，韩信带兵「多多益善」，见《史记·淮阴侯列传》；会用人是帝业成功的根。父书空读，谁言赵括善知兵：赵括是名将赵奢之子，只会背父亲的兵书、不会随机应变，蔺相如说他「徒能读其父书传，不知合变」，长平之战代廉颇为将大败，成语「纸上谈兵」由此而来。对法：贾客对仙人、君山对缑岭、秋弄笛对夜吹笙（时间加乐器）；帝业对父书、独兴对空读（一兴一空）、汉高对赵括（一成一败）、尽道对谁言。韵：笙 shēng、兵 bīng 属下平八庚；笛 dí 入声、将 jiàng 去声，出句不入韵。落点：会用人是本事，死读书会误事；本领要用在实处。下一课预告「功对业，性对情。月上对云行」（八庚其二开篇）。',
