        description: '对韵段，原文：「春秋笔，月旦评。东作对西成。隋珠光照乘，和璧价连城。」此为《笠翁对韵·下平八庚》其二续段，前接 780 课。春秋笔：孔子作《春秋》，一字寓褒贬，后人称「春秋笔法」；《孟子》说「孔子成《春秋》，而乱臣贼子惧」。月旦评：东汉汝南许劭、许靖兄弟每月初一品评乡里人物，月初叫「旦」，故称「月旦评」；曹操曾求许劭品评，得「治世之能臣，乱世之奸雄」。东作对西成：出自《尚书·尧典》「平秩东作」「平秩西成」，东作是春耕，西成是秋收。隋珠光照乘：隋侯见大蛇受伤给它敷药，蛇衔明珠相报，即隋侯之珠；乘读 shèng，四马一车为一乘，珠光能照亮前后车队。和璧价连城：卞和在荆山得玉，献三次才被认，即和氏璧；秦昭王愿以十五城易之，蔺相如完璧归赵，「价值连城」由此来。对法：笔对评一写一说，春秋对月旦一年对一月；东对西方位，作对成一始一终；隋对和国名，珠对璧宝物；光对价一亮一贵。韵：评 píng、成 chéng、城 chéng 同属下平八庚；笔 bǐ 上声、乘 shèng 去声，在分句句尾不入韵。落点：一支笔能定人褒贬，一张嘴能定人高下；两件至宝，一个靠光一个靠价，都在说「分量」。下一课预告「三箭三人唐将勇，一琴一鹤赵公清」（八庚其二七言联）。',
