        path: 'lessons/782-san-jian-san-ren-tang-jiang-yong/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「三箭三人唐将勇，一琴一鹤赵公清。汉帝求贤，诏访严滩逢故旧；宋廷优老，年尊洛社重耆英。」此为《笠翁对韵·下平八庚》其二收尾段，前接 781 课。三箭三人唐将勇：唐高宗龙朔二年，九姓铁勒聚众十余万凭天山拒唐军，薛仁贵连发三箭射杀三人，余众下马请降，军中歌「将军三箭定天山，壮士长歌入汉关」。一琴一鹤赵公清：北宋赵抃（抃读 biàn）任殿中侍御史，京师称「铁面御史」；知成都府时匹马入蜀，只带一琴一鹤，宋神宗问「为政简易，亦称是乎」，谥清献。汉帝求贤，诏访严滩逢故旧：汉光武帝刘秀与严光（字子陵）少年同学，即位后令人按形貌寻访，三请才来，同床共卧，后归耕富春山，后人名其钓处为严陵濑（严滩）。宋廷优老，年尊洛社重耆英：元丰五年文彦博留守洛阳，与富弼等老臣置酒赋诗，人称「洛阳耆英会」，规矩是「尚齿不尚官」，按年龄排座不按官位；耆读 qí，六十岁以上称耆。对法：三箭对一琴、三人对一鹤，数目对数目；唐将勇对赵公清，一武一文；汉帝对宋廷、求贤对优老、严滩对洛社。韵：清 qīng、英 yīng 同属下平八庚；勇 yǒng 上声、旧 jiù 去声，在出句句尾不入韵。落点：武要勇，官要清；贤要访，老要尊。下一课预告「昏对旦，晦对明。久雨对新晴」（八庚其三开篇）。',
