        path: 'lessons/783-hun-dui-dan-hui-dui-ming/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「昏对旦，晦对明。久雨对新晴。蓼湾对花港，竹友对梅兄。」此为《笠翁对韵·下平八庚》其三开篇，前接 782 课。昏对旦：昏是太阳落山天刚黑，旦是太阳出地平线天亮了，「元旦」的旦即此义；昏对旦是一天的两头。晦对明：晦是农历每月最后一天，月亮全不见，本义昏暗；明是日月同光、亮堂堂；晦对明是一月里的暗与亮。久雨对新晴：久雨是连下多日不停，新晴是刚放晴，久对新是日子很长对刚刚发生，雨对晴是水对光。蓼湾对花港：蓼读 liǎo，水边草本，秋天开细碎红花，一开一片，故水边一片称蓼花滩；港是能停船的水湾，花港是开满花的港湾，西湖十景有「花港观鱼」；湾对港都是水边，一野一巧。竹友对梅兄：以竹为友、以梅为兄是拟人说法；竹心虚有节、四季常青，苏轼说「不可居无竹」；梅花偏在最冷时开，松竹梅并称「岁寒三友」；友对兄都是称呼。对法：明暗对明暗、晴雨对晴雨、水边对水边、草木对草木，四副全是眼前景。韵：明 míng、晴 qíng、兄 xiōng 同属下平八庚；旦 dàn 去声、港 gǎng 上声，在分句句尾不入韵。落点：天黑天亮、雨停天晴、水边花草、竹梅为友——好对子不必找奇景，身边就是文章。下一课预告「黄石叟，丹丘生。犬吠对鸡鸣」（八庚其三续段）。',
