        num: '786',
        id: '786-geng-dui-jia-yi-dui-ding',
        title: '对韵 · 天干朝廷',
        subtitle: '九青对课',
        path: 'lessons/786-geng-dui-jia-yi-dui-ding/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「庚对甲，乙对丁。魏阙对彤庭。梅妻对鹤子，珠箔对银屏。」此为《笠翁对韵·下平九青》其一开篇，前接 785 课，八庚其三至此完结。庚对甲，乙对丁：天干共十位（甲乙丙丁戊己庚辛壬癸），古人用以记年、记日、排次序；甲为第一位、庚为第七位，相隔六位，同为阳干，命理上称甲庚相冲；乙为第二位、丁为第四位，同为阴干，一前一后相配。魏阙：古代宫门外两旁立高台，中间留通道，空处曰阙；魏同巍，谓其高耸，魏阙即最高大的阙门。政令多颁于阙下，臣子亦候朝于阙下，故以魏阙代指朝廷；《庄子·让王》「身在江海之上，心居乎魏阙之下」，谓人虽归隐而心系朝廷。彤庭：彤为红色，汉代宫殿以朱漆涂饰庭院，一片殷红，故称彤庭，亦指朝廷；班固《西都赋》「玄墀扣砌，玉阶彤庭」。梅妻鹤子：北宋林逋（读 bū），字君复，隐居杭州西湖孤山二十年，足不入城市，不娶无子，植梅养鹤为伴，人谓「梅以妻之，鹤以子之」，故称梅妻鹤子，后喻清高隐居；其《山园小梅》「疏影横斜水清浅，暗香浮动月黄昏」为咏梅绝唱，卒谥和靖先生。珠箔：箔读 bó，即帘；以珍珠串缀为帘，富贵之家方有。银屏：银制或镶银之屏风，设于内室。白居易《长恨歌》「珠箔银屏迤逦开」，正用此二物。对法：庚对甲、乙对丁是天干对天干；魏阙对彤庭同为朝廷代称，一在门外一在院中；梅妻对鹤子以花鸟为家人，珠箔对银屏为富贵陈设，一素一艳。韵：丁 dīng、庭 tíng、屏 píng 同属下平九青；甲 jiǎ 入声、子 zǐ 上声，在分句句尾不入韵。落点：字要对得齐，意要对得开——天干对天干最齐，梅鹤对珠屏最开。下一课预告「鸳浴沼，鹭飞汀。鸿雁对鹡鸰」（九青其一续段）。',
        status: 'ready',
        duration: '约 15 分钟',
