        subtitle: '九青对课',
        path: 'lessons/787-yuan-yu-zhao-lu-fei-ting/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「鸳浴沼，鹭飞汀。鸿雁对鹡鸰。人间寿者相，天上老人星。」此为《笠翁对韵·下平九青》其一续段，前接 786 课。鸳浴沼：鸳即鸳鸯，一雄一雌，成双不离，古诗文常用以喻夫妻恩爱；沼为池沼，浴是戏水沐浴，写鸳鸯在池中成双嬉游。鹭飞汀：鹭即白鹭，长颈长腿，立水浅处伺鱼；汀读 tīng，指水边平地、小洲；一群白鹭自沙洲上飞起，是水乡最常见的一幕。鸿雁对鹡鸰：鸿雁即大雁，秋南春北，飞行成行曰雁行，古人以雁为信使（《汉书·苏武传》雁足系帛书），又因雁行有序以喻兄弟长幼；鹡鸰读 jí líng，一种水边小鸟，离群则急鸣求伴，《诗经·小雅·常棣》「脊令在原，兄弟急难」，脊令即鹡鸰，故后世以鹡鸰喻兄弟患难相救。人间寿者相：相读 xiàng，指相貌、骨相；旧时看相论寿夭，谓长寿之人自有寿相；「寿者相」本为佛教语，《金刚经》「我相、人相、众生相、寿者相」，原指对寿命长短的执着，此处化用为长寿的福相。天上老人星：即南极老人星，南天最亮之星，古以为主寿，故又称寿星；《史记·天官书》「狼比地有大星，曰南极老人。老人见，治安；不见，兵起」，谓此星出现则天下太平；秦汉已有寿星祠，祭之以祈福寿。对法：鸳对鹭两种水鸟，浴对飞一在水一在天；鸿雁对鹡鸰，一寄远信一救急难；人间对天上，寿者相对老人星，天人相应。韵：汀 tīng、鸰 líng、星 xīng 同属下平九青；沼 zhǎo 上声、相 xiàng 去声在分句句尾不入韵。落点：写鸟是写人，望星是望寿——景里有情，情里有人。本课为本门类第二百课。下一课预告「八月好修攀桂斧，三春须系护花铃」（九青其一七言联）。',
