        path: 'lessons/788-pan-gui-hu-hua-ling/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「八月好修攀桂斧，三春须系护花铃。江阁凭临，一水净连天际碧；石栏闲倚，群山秀向雨馀青。」此为《笠翁对韵·下平九青》其一末段，前接 787 课。八月好修攀桂斧：八月指农历八月，桂花开放，又是乡试（秋闱）之期；攀桂即折桂，喻科举登第，《晋书·郤诜传》「犹桂林之一枝，昆山之片玉」，后世遂以蟾宫折桂称登科；要攀桂枝先得把斧头修利，故说「好修攀桂斧」，是趁时备办、待时而取的意思。三春须系护花铃：三春指春季三个月，孟春、仲春、季春；护花铃是系在花梢上的小铃，鸟雀来啄花便拉铃惊走，事见五代王仁裕《开元天宝遗事》，唐玄宗之兄宁王李宪爱花，用红丝绳缀金铃系于花梢，每有乌鹊翔集，命园吏掣铃索惊之，是惜花的故事；「须系」是说趁春早系，护得一年花事。江阁凭临，一水净连天际碧：江阁是江边的楼阁，凭临是凭栏远望；一水指满江之水，净是澄净，天际是天的尽头，江水澄净，望去直与天边的一片碧色连成一体。石栏闲倚，群山秀向雨馀青：石栏是石砌的栏杆，闲倚是闲着身子靠上去；雨馀即雨后，群山经雨洗过，秀色更向人前透出一层青来。对法：八月对三春是时令对时令，好修对须系是虚字加动词，攀桂斧对护花铃是器物对器物，一进取一爱惜；江阁对石栏是建筑对建筑，凭临对闲倚是动作对动作，一水对群山是水对山，净连对秀向，天际碧对雨馀青是方位对颜色。韵：铃 líng、青 qīng 同属下平九青；斧 fǔ 上声、碧 bì 入声，在分句句尾不入韵。落点：前两句写人做的事，后两句写眼看的天——一边进取，一边爱惜；一水连天，群山带雨，境界一下就开了。本课为本门类第二百零一课。下一课预告九青其二开篇。',
        status: 'ready',
        duration: '约 15 分钟',
        subject: 'liwengduiyun',
