        num: '789',
        id: '789-wei-luan-tai-ning',
        title: '对韵 · 泛梗浮萍',
        subtitle: '九青对课',
        path: 'lessons/789-wei-luan-tai-ning/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「危对乱，泰对宁。纳陛对趋庭。金盘对玉箸，泛梗对浮萍。」此为《笠翁对韵·下平九青》其二开篇，前接 788 课。危对乱：危是危险不安，乱是动荡无序，都指时局不好；泰对宁：泰是安泰，《周易》有泰卦，天地交而万物通，宁是安宁，指太平好年头；危乱与泰宁正反相对，一句坏年头，一句好年头。纳陛：陛读 bì，就是宫殿的台阶；纳陛是古代天子赏给最重臣子的「九锡」之一，在殿基上凿出斜阶，受赐的大臣可以沿着陛上直达殿前；受纳陛，是人臣的极大荣宠。趋庭：典出《论语·季氏》，孔子独自站在庭院里，儿子孔鲤快步走过庭前，孔子问他学诗没有、学礼没有，教他「不学诗，无以言」「不学礼，无以立」；后来「趋庭」「过庭之训」就专指承受父亲的教导。金盘对玉箸：箸读 zhù，就是筷子；金盘配玉箸，是富贵人家的器物；古人诗里「玉箸」也用来比喻眼泪，如高适《燕歌行》「玉箸应啼别后」。泛梗对浮萍：梗是断落水中的草木枝梗，随水漂流，典出《战国策·齐策》桃梗与土偶的故事；浮萍是无根的水草，随风逐水；两样东西都漂在水上没有定处，古人用来比喻漂泊无依的人生。对法：危乱对泰宁是反对；纳陛对趋庭，一个是殿上的荣宠，一个是庭前的家训；金盘对玉箸是器物对器物，金对玉；泛梗对浮萍，都是水上漂的无根之物。韵：宁 níng、庭 tíng、萍 píng 同属下平九青；乱 luàn 去声、陛 bì 去声、箸 zhù 去声、梗 gěng 上声，在分句句尾不入韵。落点：殿上的荣、庭前的教、水上的漂，三样摆在一起，看尽人间行路难。本课为本门类第二百零二课。下一课预告九青其二续段。',
        status: 'ready',
        duration: '约 15 分钟',
