        num: '791',
        id: '791-yan-ge-zhao-wu',
        title: '对韵 · 燕歌赵舞',
        subtitle: '九青对课',
        path: 'lessons/791-yan-ge-zhao-wu/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「秋首田中禾颖重，春馀园内菜花馨。旅次凄凉，塞月江风皆惨淡；筵前欢笑，燕歌赵舞独娉婷。」此为《笠翁对韵·下平九青》其二末段，前接 790 课。秋首田中禾颖重：秋首是秋季开头；颖读 yǐng，是禾穗的芒尖，禾颖就是田里的谷穗；重读 zhòng，沉甸甸；秋天一开始，田里的稻穗就沉甸甸压弯了秆，收成在望。春馀园内菜花馨：春馀就是暮春，馀读 yú；馨读 xīn，香气远闻；春天将尽，园子里的菜花正开得香。旅次凄凉，塞月江风皆惨淡：旅次是旅途中暂住歇脚的地方；塞月读 sài，是边塞的月亮，江风是江上的风；漂泊在外的人看什么都是凄凉的，塞上的月、江上的风都显得惨淡——月色本无恨，愁人见月生愁。筵前欢笑，燕歌赵舞独娉婷：筵读 yán，是酒席；燕读 yān，是战国燕国，古时说燕赵多佳人，燕歌赵舞泛指好看动人的歌舞；娉婷读 pīng tíng，姿态美好；酒席上一片欢笑，只有燕歌赵舞最叫人挪不开眼。对法：秋首对春馀是时令对时令；田中对园内是地方对地方；禾颖重对菜花馨，一重一香；旅次对筵前、凄凉对欢笑是反对；塞月江风对燕歌赵舞，皆惨淡对独娉婷，一苦一乐。韵：馨 xīn、婷 tíng 同属下平九青；重 zhòng 去声、淡 dàn 去声，在分句句尾不入韵。落点：前两句写田里的收成、园里的花香，后两句一冷一热——同一片天底下，苦乐各不相同；景没变，变的是看景的人。本课为本门类第二百零四课，九青其二至此完结。下一课预告十蒸其一开篇。',
