        grade: '小学低中年级',
        description: '对韵段，原文：「谈对吐，谓对称。冉闵对颜曾。侯嬴对伯嚭，祖逖对孙登。」此为《笠翁对韵·下平十蒸》其二开篇，前接 794 课。谈对吐：谈、吐都是说话，谈吐合起来就是说一个人说话的样子。谓对称：谓是告诉、说；称读 chēng，是称说、称呼；谓和称都是「说」。冉闵对颜曾：冉闵是十六国时期魏国的皇帝，勇猛善战；颜曾是颜回和曾参，孔子的两位最贤的弟子；一主二贤，人名对人名。侯嬴对伯嚭：侯嬴是战国魏国的守门小吏，信陵君的门客，为他出「窃符救赵」的计策，事情办成自己自杀送行，是个贤士；伯嚭读 bó pǐ，是春秋吴国的大夫，收受越国贿赂、进谗言害了伍子胥，是个奸臣；一贤一奸，正好成对。祖逖对孙登：祖逖读 zǔ tì，是东晋名将，「闻鸡起舞」「中流击楫」的典故主角，带兵北伐中原；孙登是三国吴国的太子，孙权的长子，以贤德出名；一武一文，正好成对。对法：谈对吐是动词对动词；谓对称也是说；冉闵对颜曾、侯嬴对伯嚭、祖逖对孙登，人名对人名，贤奸相对、文武相对。韵：称 chēng、曾 zēng、登 dēng 同属下平十蒸；吐 tǔ 上声、闵 mǐn 上声、嚭 pǐ 上声，在分句句尾不入韵。落点：这一串全是人名——贤的、奸的、文的、武的都有；念对子也是认人物，读着读着，历史就在对子里了。本课为本门类第二百零八课。下一课预告十蒸其二续段。',
